-- 0262 oleoturismo (inventario_oleoturismo_pdf) — entidades + puntuaciones
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23060','oleoturismo','Almazara del Cortijo de El Madroño y Cooperativa San Amador','Penaliza levemente en infraestructura vanguardista de atención al turista frente a Bailén, pero sobresale en valor antropológico, arqueología industrial del siglo XIX y regularidad en los sellos provinciales de calidad. Fiesta de la Aceituna (8 de diciembre). Evento institucionalizado donde se extrae aceite crudo in situ usando una prensa de viga con husillo de madera, recreando la molienda preindustrial antes de repartir el tradicional canto de pan con aceite, hoyo martense.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23092','oleoturismo','Cortijo de Espíritu Santo (Ctra. Úbeda-Jódar, Km 4)','(Destaca por la altísima calidad en la atención personalizada y por ofrecer la vivencia completa del cortijo tradicional andaluz). Jornadas de Cosecha en Familia (octubre y noviembre), fines de semana especiales donde se dota a los niños y adultos de herramientas tradicionales para varear de forma lúdica. Paseo guiado a pie por el olivar familiar explicando los ciclos ecológicos del árbol y los métodos de labranza.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24010','oleoturismo','Museo de la Cultura del Olivo de la Hacienda La Laguna (Puente del Obispo) y','Sobresaliente en el sector por su capacidad receptiva de visitantes internacionales y sus marcas galardonadas repetidamente con el premio Alimentos de España. Feria de Turismo de Interior de Andalucía (Tierra Adentro), donde Baeza ejerce como eje articulador de la comercialización de paquetes oleoturísticos, sumado a los certámenes de cocina con AOVE.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24011','oleoturismo','S.C.A. Agrícola de Bailén Virgen de Zocueca (Picualia) y Aceites Oro Bailén (Galbasa)','Máxima nota provincial actual debido a que Picualia ostenta el Premio Especial Alimentos de España al Mejor AOVE y Oro Bailén lidera los primeros premios internacionales Mario Solinas. Fiesta de la Batalla de Bailén (julio, vertiente histórica ligada al suministro de aceite al ejército) y las jornadas técnicas de apertura de campaña (principios de octubre), donde se abren las instalaciones a expertos mundiales para presenciar la primera molienda en verde.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23020','oleoturismo','S.C.A. San Benito (Tierras de Canena) y el entorno patrimonial del Castillo de Canena (finca e instalaciones del grupo oleícola homónimo)','Sobresaliente en innovación biotecnológica de campo y galardones internacionales permanentes, incluyendo el distintivo Jaén Selección. Jornadas de Biodiversidad y Sostenibilidad en el Olivar (marzo), donde se exponen los avances técnicos en agricultura de conservación y regenerativa frente al cambio climático.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24015','oleoturismo','Oleoturismo Jaén - San Francisco Oleícola S.L. (C/ Pedro Pérez, S/N)','(Máxima puntuación en atención al cliente, claridad de las explicaciones y flexibilidad de horarios para grupos pequeños). Jornadas de Cosecha Nocturna (octubre/noviembre), donde se organizan visitas especiales para ver la recepción de la aceituna verde bajo focos y el proceso de extracción en frío de madrugada. Ruta guiada por la fábrica activa para ver en directo el funcionamiento de la maquinaria de extracción moderna.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23080','oleoturismo','S.C.A. Sierra de Santo Tomé (productora de la marca Verde Salud)','Impulsado en el ranking por la obtención recurrente del distintivo institucional Jaén Selección y su certificación en el proyecto europeo de biodiversidad Olivares Vivos. Jornadas Técnicas del Aceite de Oliva Verde (noviembre), enfocadas en la formación de agricultores para la recogida selectiva de la aceituna en el punto óptimo de maduración (índice de madurez entre 1 y 2).','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23061','oleoturismo','Oleícola Jaén (instalación industrial y jardín de variedades) y el Centro de Innovación Tecnológica del Olivar (Vasca)','Elevada puntuación en el área de Infraestructura Industrial e Innovación, apoyada por sus modernos complejos de molienda y su fuerte apuesta por la divulgación científica del sector. Simposios Técnicos de Oleocultura de Mengíbar (fechas variables), donde se debaten los últimos avances en el aprovechamiento de subproductos del olivar (alperujo, hueso de aceituna y hoja) como fuentes de energía biomasa.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23081','oleoturismo','S.C.A. San Vicente (marca Sierra de Segura) y los olivares de alta montaña colgados en terrazas calizas','Destaca por poseer uno de los patrimonios paisajísticos y forestales más singulares de Europa, sumado al valor histórico de ser una de las Denominaciones de Origen de aceite de oliva más antiguas del país (aprobada en 1979). Jornadas Técnicas de la D.O.P. Sierra de Segura (coincidiendo con la entrega de los Premios Ardilla en primavera), que galardonan a los mejores aceites de la comarca recolectados a principios de campaña.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23028','oleoturismo','S.C.A. San Vicente (cooperativa comercializadora de la marca Puerta de Las Villas) y el patrimonio oleícola de la D.O.P. Aceite de Cazorla','Impulsado por el altísimo valor diferencial de su variedad autóctona Royal, sus aceites recurrentemente premiados con el galardón Jaén Selección y sus rigurosos sistemas de trazabilidad. Fiesta del Remate de Cazorla (febrero/marzo), una celebración tradicional que conmemora el fin de la campaña de recogida de la aceituna, rescatando cantos populares y gastronomía local ligada al uso del aceite nuevo.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23065','oleoturismo','S.C.A. Nuestra Señora de la Asunción y la sede central del Consejo Regulador de la D.O.P. Sierra de Segura','Relevancia estratégica alta al albergar los laboratorios de control de la calidad y los paneles de cata oficiales de la comarca serrana. Jornadas de Divulgación del Aceite de Oliva Virgen Extra Ecológico (octubre), destinadas a potenciar la transición del olivar tradicional hacia modelos libres de químicos sintéticos.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24002','oleoturismo','Museo del Aceite Alcalá Oliva S.A. (Carretera A-339, Km 50) y Aceites Florencio Aguilera (Aldea de La Hortichuela)','(Sobresaliente por combinar en un mismo espacio museo histórico, olivar visitable frente a un castillo y talleres de recogida manual). Campaña de recolección de otoño-invierno (noviembre a enero), momento en el que el museo activa los talleres vivenciales donde el turista coge la vara y el hatillo para recolectar sus propios frutos. Visita guiada a un antiguo molino de prensa de 1914 restaurado y exposición de útiles históricos de labranza.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24003','oleoturismo','S.C.A. Virgen del Perpetuo Socorro (Ctra. de Alcalá la Real, S/N) y los olivares tradicionales que trepan hacia la Sierra Ahillos','(Excelente nota por su alto valor cooperativo integrado y la gran comodidad de combinar rutas de arquitectura defensiva militar medieval con la oleocultura de alta gama). CONTROL DE LA VENTANA DE CONTEXTO Y AVANCE ALFABÉTICO: La base de datos nacional de servicios de reserva turística real ha sido expandida masivamente mediante este nuevo macro-grupo de bloques integrados. Elija el siguiente movimiento en el plan de ruta estratégico: • Continuar con el Siguiente Grupo Masivo de Bloques: Desplegar simultáneamente municipios de Cáceres (GataHurdes ampliado), Badajoz (Serena ampliado), Murcia (Valle del Ricote ampliado) y Málaga (Antequera ampliado). . Ruta peatonal "Entre Olivos y Calatravas": Paseo a pie guiado por las parcelas de olivar tradicional de ladera en pendientes pronunciadas, detallando el manejo de las cubiertas vegetales y la recogida en suelos calizos de montaña media.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23046','oleoturismo','Cortijo El Puerto (Ctra. Linares-Baeza)','(Sobresaliente por la originalidad de su ruta en remolque y su enfoque radical hacia la biodiversidad viva del campo). "Ecotour de Primavera" (abril a junio), época del esplendor de las flores de la cubierta vegetal y actividades de fotografía de aves en la propia finca. Safari ecoturístico guiado a lomos de un remolque adaptado para recorrer el mar de olivos de la finca de forma cómoda.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23039','oleoturismo','Finca El Altillo - AOVE Noviembre','(Muy valorado por su accesibilidad logística y el encanto arquitectónico de su cortijo andaluz). Fiesta del Aceite Nuevo en el Cortijo (noviembre), coincidiendo con la salida al mercado de sus botellas premium de diseño y la organización de grandes comidas comunitarias en sus patios.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23086','oleoturismo','S.C.A. San Isidro de Torredelcampo (Av. de la Constitución, S/N) y el Centro de Interpretación del Olivar de la Campiña Sur','(Excelente nota por su alto valor cooperativo integrado y la gran comodidad de su punto de venta directa de fábrica con aceites premium). Fiesta del Aceite de Cosecha Temprana de Torredelcampo (noviembre), un fin de semana festivo de gran afluencia donde el municipio organiza mercados de productores locales, catas populares gratuitas en la calle y desfiles tradicionales. Paseo guiado "Senderos de la Picual de Campiña": Ruta peatonal por el interior del término municipal para contemplar el cultivo tradicional extensivo en suelos profundos de vertisoles y el manejo agronómico de secano.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23095','oleoturismo','S.C.A. Nuestra Señora de las Mercedes (La cooperativa de aceite de oliva más grande del mundo en volumen de producción)','(Máxima puntuación en la categoría de turismo de ingeniería e industrial masivo, aunque menos íntimo para experiencias lúdicas tradicionales). Jornadas de Puertas Abiertas del "Gigante del Aceite" (coincidiendo con el pico álgido de la molturación en diciembre), registrando visitas de delegaciones comerciales de todos los continentes.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23099','oleoturismo','S.C.A. Sierra de la Pandera','(Muy valorado por su autenticidad rural y por ofrecer un contacto directo con las costumbres de la Sierra Sur de Jaén). Fiesta de la Recolección Tradicional (noviembre), un fin de semana festivo donde los turistas pueden vestirse con ropas de época y aprender a recolectar a mano usando los canastos típicos fabricados en el pueblo.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14055','oleoturismo','Aceites Vizcántar (Zagrilla, KM. 0) y operadoras locales como Touristea Priego / Paseos Priego Turísticos (C. Carrera de Álvarez, 20)','(. Apertura Oficial de la Cosecha Temprana (octubre), periodo donde las agencias locales activan los paquetes de cata en verde y los restaurantes del municipio diseñan menús especiales basados en el primer aceite del año. Ruta guiada a pie por el Olivar Monumental de Montaña en pleno Parque Natural de las Sierras Subbéticas, tocando troncos centenarios esculpidos.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14043','oleoturismo','Aceites San Antonio /','(Máxima puntuación provincial por su imbatible apuesta biotecnológica por las variedades autóctonas raras y la impecable calidad de su propuesta culinaria rústica). Feria del Olivo de Montoro (bienal, mes de mayo) y jornadas del aceite nuevo (noviembre), periodos de plena molienda donde la finca organiza catas populares y rutas cicloturísticas entre olivares centenarios.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17003','oleoturismo','S.C.A. Olivarera Nuestra Señora de Guadalupe (Av. de Castro del Río, S/N) y fincas de olivar tradicional asociadas a la D.O.P. Baena','(Sobresaliente por el extraordinario valor etnográfico de su panel de cata institucional y por la perfecta organización logística de sus visitas para grupos y particulares). Gala de los Premios a la Calidad de la D.O.P. Baena (coincidiendo con el final del otoño y el inicio de la campaña invernal), periodo donde se organizan ferias gastronómicas populares con catas gratuitas en la calle y degustaciones de aceite nuevo de primer día de molienda. Ruta peatonal por el Olivar Histórico de Campiña: Paseo guiado a pie por parcelas de relieve ondulado, descubriendo ejemplares entrelazados de las variedades Picudo y Hojiblanca en suelos arcillosos de albarizas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14019','oleoturismo','Almazara de la S.C.A. San Isidro / Aceites Guadajoz y talleres de artesanía en madera de olivo de la localidad','(Destaca por ser el único municipio que integra la artesanía en madera de olivo como un recurso turístico acoplado a la gastronomía). Feria Artesanal de la Madera de Olivo y del Aceite (septiembre/octubre), transformando el barrio de La Villa en un mercado medieval con catas callejeras permanentes. Ruta guiada combinada: Visita a las tolvas de recepción y línea de molienda moderna de la cooperativa.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41041','oleoturismo','OleoEstepa S.C.A. (Pol. Ind. Sierra Sur, C/ El Olivo) y la Ciudad del Chocolate / Museo de la Mantecada','(Excelente nota por la rigurosidad científica de sus catas y su sinergia imbatible con el turismo de repostería navideña). Campaña del Mantecado y del Aceite Nuevo (octubre a diciembre), época de masiva afluencia turística donde el municipio funciona a pleno rendimiento industrial y comercial. Tour técnico por el laboratorio central de control de calidad y la gran planta de envasado automatizada de la marca.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14042','oleoturismo','Aceites Bellido - Molino Juan Colín (Carretera A-3130, Km 27.5) y Lagar Los Raigones (Ctra. Montilla - Llano del Espinar, Km 5)','(Destaca de forma única por su doble oferta gastronómica al unificar la cultura del aceite y la del vino en una sola parada turística). Fiesta de la Pasa y el Aceite Nuevo (septiembre a noviembre), donde los turistas participan activamente en las catas al aire libre rodeados de las espectaculares vistas de la Campiña Sur. Ruta a pie por una finca tradicional que combina olivar andaluz con viñedos antiguos.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14038','oleoturismo','Cooperativa Olivarera de Lucena (Av. de la Infancia, 15) y su marca premium Lucentina','(Sobresaliente por el tamaño y capacidad de sus instalaciones y la gran variedad de productos gourmet en su agrotienda). Jornadas de Promoción de la variedad Hojiblanca (noviembre/ diciembre), coincidiendo con la entrada masiva de los frutos en el molino para la obtención de sus primeros aceites premium. Visita guiada por las macroinstalaciones industriales de la cooperativa y sus bodegas de almacenamiento de última generación.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14039','oleoturismo','Centro de Interpretación','(Elevada puntuación por su imbatible ubicación al borde de la Vía Verde y la comodidad de sus packs familiares con audioguía). Jornadas de Cicloturismo y Oleoturismo de Luque (primavera y otoño), combinando el alquiler de bicicletas con paradas para desayunar entre olivares centenarios. Ruta turística a pie por la Vía Verde del Aceite guiada, conectando de forma directa el carril cicloturista con el mar de olivos de Luque.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90740','oleoturismo','Museo del Olivo de Sierra de Adamuz e integradores locales adscritos a la D.O.P. Montoro-Adamuz','(Destaca por su alto contenido antropológico y la espectacularidad de los platos tradicionales de su degustación de cierre). Fiestas del remate y jornadas gastronómicas del aceite nuevo de sierra (enero), idóneas para probar variedades autóctonas raras como la Negrilla o el Carrasqueño de la Sierra. Visita guiada interactiva por el museo etnográfico centrado específicamente en el olivar tradicional de sierra en pendientes extremas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90741','oleoturismo','Museo HistóricoArqueológico de Almedinilla (Paraje Fuente Ribera, S/N) y la almazara familiar Aceites Manuel Molina Muñoz e Hijos S.L. (Calle Huertas, 8)','(Excelente puntuación por el valor excepcional de su museo-almazara y por permitir al turista entender la producción del aceite desde la época romana). Banquetes Romanos con AOVE (fechas variables en verano), cenas teatralizadas inspiradas en la antigüedad clásica donde todos los platos se riegan con aceites locales. Ruta guiada por el Museo Histórico alojado en una antigua almazara y molino harinero del siglo XIX, visitando la "Sala del Aceite y del Olivo".','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18143','oleoturismo','Centro de Interpretación','(Máxima puntuación de la provincia por su capacidad para unificar en un solo recorrido un molino del siglo XV, olivares nazaríes, fábricas modernas operativas y paseos botánicos). Campaña de recogida temprana de otoño (octubre-noviembre), fecha en la que Alquimia Verde y las almazaras del municipio activan las rutas de senderismo con catas a ciegas en mitad de la naturaleza. Ruta guiada por el "Olivar Nazarí La Erilla": Paseo a pie entre fincas de olivos centenarios e imponentes ejemplares protegidos a las faldas de Sierra Nevada.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18147','oleoturismo','Almazara La Flor de la Alpujarra S.C.A. (Ctra. Lanjarón-Órgiva, Km 14) y la Fábrica de Aceite Órgiva (Ctra. Albuñol, S/N)','(Valorado por la autenticidad y rusticidad de su entorno geográfico, aunque con menor infraestructura monumental de atención masiva que Nigüelas). Fiestas del Remate de la Alpujarra (enero-febrero), momento ideal para visitar el pueblo y adquirir de forma directa garrafas recién envasadas a precios de productor. Rutas de senderismo por el olivar tradicional de alta montaña y bancales escarpados de la Alpujarra.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29084','oleoturismo','LA','(Máxima puntuación provincial por su imbatible propuesta lúdica, la belleza de sus picnics camperos de diseño y su infraestructura adaptada para el turista premium extranjero). Jornadas de la Cosecha Temprana Orgánica (octubre), con talleres nocturnos de cata y maridajes exclusivos con vinos de la D.O. Sierras de Málaga. Paseo peatonal y artístico de 1 hora por un sendero botánico diseñado por Philippe Starck, combinando olivos monumentales, viñedos, huertos orgánicos y obras de arte contemporáneo expuestas al aire libre.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29083','oleoturismo','Museo Etnográfico de Riogordo (C. Iglesia, 14) y la cooperativa agroalimentaria local S.C.A. Agro-Olivarera San Juan Bautista (Av. de la Constitución)','(Sobresaliente por conservar uno de los molinos de sangre más bonitos y operativos de Andalucía y por poner en valor su variedad dulce autóctona). Fiesta de la Molienda de Riogordo (finales de febrero), un fin de semana completo donde el pueblo entero se viste de época y se pone en marcha el molino antiguo triturando aceitunas en directo con animales ante los turistas. Ruta histórica guiada por el Museo Etnográfico, alojado en una casa-molino tradicional del siglo XIX perfectamente conservada.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04088','oleoturismo','Oro del Desierto - Rafael Alonso Aguilera S.L. (Ctra. Nacional 340, Km 472) y el Museo del Aceite de Oliva de Tabernas (ubicado en una almazara restaurada de 1925)','(Espectacular puntuación por el valor de su restaurante oleícola integrado, sus sistemas solares sostenibles y el increíble palmarés de sus botellas de diseño). Jornadas de la Cosecha del Desierto (octubre-noviembre), momento en el que el complejo activa talleres interactivos donde los turistas pueden ver la extracción a temperaturas bajísimas en mitad de un clima árido. Tour de Oleoturismo en el Desierto: Paseo guiado a pie por las fincas de olivar ecológico situadas en el entorno único del Desierto de Tabernas, explicando cómo se gestiona el agua mediante goteo solar de precisión.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43156','oleoturismo','Museo Natural de Olivos Milenarios del Arión (Finca del Arión) y el molino productor Villarroya / Olis de l''Arion','(. Jornadas Gastronómicas del Aceite de Oliva de Ulldecona (octubre y noviembre), coincidiendo con la campaña selectiva de recolección de los árboles patrimoniales, donde los restaurantes locales crean menús especiales con hilos de este aceite. Ruta peatonal guiada por el Museo Natural al aire libre: Recorrido a pie entre la mayor concentración de olivos monumentales del mundo, contemplando de cerca la "Farga del Arión" (olivo datado científicamente mediante datación perimetral con más de 1.700 años de antigüedad, plantado en época del emperador Constantino).','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43068','oleoturismo','S.C.A. Salvador de Godall (C/ de la Cooperativa, 1) y los olivares monumentales de la comarca del Montsià','(Excelente nota por su fuerte apuesta por las variedades autóctonas raras y la comodidad de su agrotienda y visitas colectivas). Fira de l''Oli de Godall (celebrada anualmente el segundo fin de semana de marzo), uno de los mercados sectoriales más antiguos de la comarca que congrega a miles de visitantes para catar y comprar el aceite nuevo recién embotellado. Visita guiada peatonal por el interior de la almazara cooperativa, recorriendo las líneas de limpieza, batido en frío y las imponentes bodegas de acero inoxidable.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12121','oleoturismo','Intercoop / Olis Cuquello (Finca Cuquello, Ctra. San Rafael) y el paraje monumental de la Font de la Salut','(Sobresaliente por la excelente organización de sus desayunos camperos y el valor único de recuperar y embotellar la variedad monovarietal Cuquello). Feria Romana de Traiguera (octubre) y rutas especiales de otoño, donde se conecta la historia comercial del aceite en la Vía Augusta con las catas de los primeros aceites del año. Paseo guiado "Ruta de los Olivos Milenarios de Cuquello": Recorrido a pie por olivares monumentales esculpidos con formas espectaculares por el paso de los siglos.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50045','oleoturismo','Almazara Molino Alfonso (Ctra. Almonacid, S/N)','(Destaca por la excelente estructuración de sus packs de reserva online y su infraestructura turística de primer nivel). Jornadas del Aceite Nuevo (noviembre-diciembre), coincidiendo con la molienda de las primeras aceitunas Empeltre en verde para capturar perfiles afrutados intensos antes del invierno. Paseo peatonal por el "Olivar Centenario de Belchite": Ruta a pie guiada entre olivos de la variedad Empeltre con troncos retorcidos por el cierzo.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43002','oleoturismo','Apadrinaunolivo.org','(Sobresaliente por el tremendo valor emocional y social de la experiencia, además de la originalidad de sus catas de la variedad Royal de Alloza). Encuentros de Padrinos y Madrinas (primavera y otoño), fines de semana festivos donde se organizan visitas masivas, comidas comunitarias y talleres de poda y mantenimiento del olivar. Ruta ecoturística y social por los olivares recuperados: Recorrido a pie guiado para conocer el proyecto de recuperación de olivos abandonados de la variedad Empeltre y la rara variedad autóctona Royal de Alloza.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07023','oleoturismo','Cooperativa de Sóller (Ctra. de Fornalutx, 8) y la finca olivarera monumental Finca Can Det (C. de Can Det, 20)','(Máxima puntuación por conservar un patrimonio preindustrial único en el mundo en perfecto estado de funcionamiento y su excelente menú de campo). Jornadas del Aceite de la Sierra de Tramuntana (octubre-noviembre), coincidiendo con la recogida manual en los bancales empinados e inaccesibles para maquinaria pesada. Paseo por el Olivar de Montaña de Tramuntana: Senderismo guiado entre bancales de piedra seca declarados Patrimonio de la Humanidad por la UNESCO, contemplando olivos monumentales con troncos retorcidos por la roca caliza de la isla.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45106','oleoturismo','Patrimonio Oleícola /','(Máxima puntuación de la meseta central por su espectacular centro de interpretación interactivo y la altísima calidad didáctica de sus menús de cata). Fiesta del Olivo de Mora (último fin de semana de abril), Declarada de Interés Turístico Nacional, donde el pueblo entero se llena de desfiles de carros tradicionales engalanados, catas callejeras multitudinarias y concursos de destreza agrícola. Ruta guiada por el olivar "5 Elementos": Paseo a pie entre fincas de cultivo intensivo y tradicional para conocer de primera mano el manejo agrícola de la comarca.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45087','oleoturismo','Almazara García de la Cruz S.L. (C/ Rey Juan Carlos I, 117) y el patrimonio de molinos de viento tradicionales de la comarca','(Sobresaliente por la excelente organización de sus packs que enlazan dos joyas como el aceite y el azafrán, sumado a la comodidad de sus accesos llanos desde la autovía A-4). CONTROL DE LA VENTANA DE CONTEXTO Y AVANCE ALFABÉTICO: La base de datos nacional de servicios de reserva turística real ha completado una nueva expansión de máxima densidad con los registros ampliados de los núcleos capitales históricos de España (Martos, Priego, Estepa y Madridejos). Elija la siguiente directriz estratégica de avance en el sistema:. . Ruta botánica "Óleo-Azafrán": Paseo a pie guiado por las parcelas rústicas de secano, detallando el manejo agrícola del olivar centenario de la variedad Cornicabra combinado con el cultivo tradicional del azafrán.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10205','oleoturismo','Almazara As Pontis Agropecuaria Carrasco S.L. (Ctra. CC-65.1, Km 0.5) y sus marcas multipremiadas bajo la variedad Manzanilla Cacereña','(Sobresaliente por el espectacular palmarés internacional de sus aceites Vieiru y la perfecta adaptación de sus instalaciones para recibir visitas con degustaciones camperas completas). Jornadas del Aceite Nuevo en Sierra de Gata (noviembre-diciembre), época en la que la almazara se llena de vida permitiendo a los turistas probar el zumo de aceituna sin filtrar recién salido del decánter. Ruta peatonal "Entre Olivos en Sierra de Gata": Senderismo guiado a pie por fincas de alta pendiente en un microclima atlántico-mediterráneo rodeado de valles de castaños y robles.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06087','oleoturismo','S.C.A. del Campo Virgen de la Consolación (Ctra. de Castuera, S/N) y el Museo Tecnológico del Aceite de Oliva de Monterrubio','(Excelente puntuación por el rigor de su museo tecnológico y su imbatible oferta de maridaje con embutidos ibéricos autóctonos). Jornadas de la Cosecha y el Aceite Nuevo (diciembre), momento en el que el municipio abre sus cooperativas al público para la compra directa y organiza degustaciones multitudinarias de migas extremeñas regadas con el primer caldo del año.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31068','oleoturismo','La','(Sobresaliente por la excelente organización de sus talleres culinarios y por demostrar la calidad y suavidad de los aceites producidos en el límite norte de cultivo de la península). Fiesta de la Tostada y el Aceite Nuevo de Cascante (celebrada habitualmente a finales de enero o principios de febrero), donde miles de turistas acuden a probar las rebanadas de pan tostado con el primer aceite del año distribuidas de forma festiva en las calles. Ruta a pie por el "Olivar de la Ribera del Ebro": Paseo peatonal guiado entre plantaciones tradicionales de la variedad Empeltre y parcelas modernas de Arbequina adaptadas al clima frío del norte.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26120','oleoturismo','Almazara El Tilo / Aceite Deleyda (Ctra. de Arnedo, Km 1.2) y el barrio histórico de bodegas y tinaos excavados en roca','(Destaca por su imbatible propuesta de maridaje rústico y por ser un referente en la producción integrada y ecológica del norte peninsular). Jornadas Gastronómicas del Aceite Ecológico de La Rioja (noviembre y diciembre), periodo en el que la almazara abre sus puertas para degustar los primeros aceites del año recién extraídos en frío. Ruta peatonal por los olivares de alta montaña de la Rioja Baja: Paseo guiado a pie por parcelas tradicionales en terrazas calizas, explicando la convivencia del olivo con el viñedo y el almendro.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41039','oleoturismo','1948 Óleum - Finca El Tejar (Ctra. Écija-Herrera, Km 12)','(Sobresaliente por el encanto arquitectónico de su finca colonial andaluza, la limpieza absoluta de sus instalaciones y el rigor pedagógico de sus cursos de cata). "La Cosecha Nocturna de 1948 Óleum" (octubre), un evento premium exclusivo bajo reserva donde un grupo reducido de turistas acompaña a los operarios en la recolección nocturna con maquinaria para evitar las altas temperaturas del día. Paseo guiado a pie por el Olivar Ecológico e Integrado: Ruta botánica y técnica entre olivos de la variedad Morisca y Arbequina, detallando la gestión biológica del suelo y la recuperación de fauna útil.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17210','oleoturismo','Oli de Ventalló -','(Sobresaliente por el gran valor diferencial de su propuesta y por ser uno de los máximos baluartes en la defensa de la variedad minoritaria Argudell). Jornadas del Aceite Nuevo del Empordà (noviembre y diciembre), un periodo festivo donde la masía organiza catas a ciegas en su patio central para presentar los aceites verdes de la temporada recién molturados. Ruta peatonal por el Olivar del Empordà: Paseo guiado a pie entre olivares tradicionales que crecen bajo la influencia directa del viento de la Tramuntana y el clima mediterráneo de la Costa Brava.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90147','oleoturismo','Almazara Molino de Almonacid (Instalaciones colindantes adscritas a la producción del Campo de Belchite) y la Presa Romana de Almonacid (la más alta del Imperio Romano conservada en el mundo)','(Excelente nota por su imbatible conexión paisajística y arqueológica, convirtiendo una caminata técnica por el campo en una clase magistral de historia de la agricultura). Rutas del Cierzo y el Aceite (otoño e invierno), coincidiendo con las fechas de máxima actividad industrial en las almazaras de la cuenca del Ebro. Ruta combinada "Agua e Historia del Aceite": Paseo a pie guiado por senderos que conectan los olivares tradicionales de secano de la variedad Empeltre con el espectacular cañón del río Aguasvivas y la presa romana del siglo I d.C.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11024','oleoturismo','S.C.A. Los RemediosPicasat (Ctra. de Ronda, Km 1) y la Vía Verde de la Sierra','(Sobresaliente por el espectacular paisaje de montaña que rodea sus fincas y el altísimo valor culinario de maridar sus aceites con el icónico queso Payoyo). Feria del Olivar y del Aceite de Oliva Virgen Extra de la Sierra de Cádiz (Olivera, celebrada habitualmente en el mes de abril), donde el casco histórico se llena de expositores gastronómicos, concursos de tapas regadas con AOVE y catas populares gratuitas. Ruta combinada "Vía Verde y Olivar de Montaña": Paseo a pie o cicloturista guiado por los senderos e infraestructuras del antiguo trazado ferroviario, cruzando olivares cultivados en pendientes extremas sobre suelos pedregosos.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28146','oleoturismo','Oleum Laguna /','(Excelente puntuación por su capacidad para estructurar un producto lúdico impecable a menos de 40 minutos de Madrid central y el gran palmarés ecológico de sus marcas). Fiesta del Aceite de Oliva de la Comunidad de Madrid y jornadas del aceite nuevo (noviembre y diciembre), organizando visitas especiales donde el turista puede embotellar su propio AOVE sin filtrar directo de la línea de molturación. Ruta peatonal "Entre Olivos del Tajuña": Paseo a pie guiado por las parcelas de olivar tradicional de la vega madrileña, explicando la adaptación del olivo a los inviernos rigurosos de la meseta.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19045','oleoturismo','Almazara Alcarria Baja Aceite Castúo (Ctra. de Sacedón, S/N) y el mar de olivos que rodea el embalse de Entrepeñas','(Destaca por poner en valor una de las variedades de aceituna más singulares y minoritarias del norte de la meseta peninsular). Jornadas del Aceite Nuevo Alcarreño (noviembre y diciembre), periodo de máxima actividad industrial donde se organizan visitas para ver la molienda verde y comprar el zumo sin filtrar recién salido del decánter. Paseo guiado a pie por los olivares de la Alcarria: Ruta peatonal entre parcelas de bancales de alta montaña y secano rústico, explicando la dureza del clima alcarreño.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07063','oleoturismo','Finca Son Moragues (Ctra. de Valldemossa a Deià, Km 2.5)','(. Jornadas de la Oliva Mallorquina (octubre y noviembre), época en la que la finca activa sus talleres de recogida manual en los bancales empinados e inaccesibles para cualquier tipo de maquinaria pesada. Ruta histórica y botánica guiada por la posesión mallorquina: Paseo a pie entre majestuosos bancales de piedra seca declarados Patrimonio de la Humanidad por la UNESCO, tocando olivos monumentales con troncos retorcidos de más de 500 años.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23067','oleoturismo','S.C.A. San Joaquín (Ctra. de Mancha Real, S/N) y el sistema histórico de huertas y terrazas de la Charca de Pegalajar','(Excelente nota por su valor etnológico integrado y por poner en valor el cultivo del olivar tradicional de alta pendiente alimentado por manantiales naturales). Jornadas del Aceite de Cosecha Temprana de Sierra Mágina (noviembre), un fin de semana festivo donde el municipio organiza catas populares y rutas de senderismo fotográfico por el paisaje agrícola. Ruta combinada "Agua y Olivar de Montaña": Paseo a pie guiado por los senderos tradicionales que conectan la famosa Charca y su sistema de riego islámico con los olivares cultivados en las laderas de Sierra Mágina.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23055','oleoturismo','Almazara San Carlos Pago de Cirsus / Aceites Nobleza del Sur (Ctra. de Torreblascopedro, Km 0.5)','(Máxima puntuación de la comarca norte por su imbatible propuesta pedagógica de cata, su diseño estético y el enorme palmarés de sus marcas). Experiencia Primera Prensada de Otoño (octubre), un evento premium donde los turistas acompañan en la recogida temprana, asisten a la molienda verde esmeralda y embotellan su propio lote exclusivo de la temporada. Paseo peatonal por el "Olivar de Abejas y Biodiversidad": Ruta a pie guiada entre fincas de producción integrada para conocer la flora silvestre y los polinizadores que conviven con el árbol.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30019','oleoturismo','Almazara Deortegas S.L. (Paraje Los Charcos, Ctra. de Jumilla)','(Sobresaliente por la excelente organización de sus talleres, la belleza estética de su almazara integrada en la naturaleza y el enorme palmarés ecológico de sus marcas). Jornadas de Oleoturismo y Floración de Cieza (marzo) y la Fiesta del Aceite Nuevo Ecológico (noviembre), épocas del año donde se activan gincanas familiares y catas a ciegas abiertas al público. Ruta peatonal "Entre Olivos del Altiplano": Paseo a pie guiado por las fincas de cultivo 100% ecológico de secano, explicando cómo sobrevive el olivar tradicional en climas de baja pluviometría.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05207','oleoturismo','Almazara El Terruño / Aceite de Oliva Gredos y los olivares en bancales a los pies de la Sierra de Gredos','(Destaca por la espectacularidad de su paisaje de montaña, su fuerte enfoque artesanal y el encanto rústico de su degustación gastronómica). Jornadas del Aceite Nuevo de Gredos (noviembre y diciembre), organizando visitas especiales donde el turista puede embotellar directamente su propio AOVE verde sin filtrar directo de la prensa mecánica continua. Ruta peatonal "Olivares de Alta Montaña": Paseo a pie guiado por las impresionantes laderas del Valle del Tiétar, descubriendo olivos cultivados en terrazas de piedra en un microclima de montaña protegido del viento del norte.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18066','oleoturismo','S.C.A. San Isidro de Deifontes (Av. de la Constitución, S/N) y el paraje del Nacimiento del Río Cubillas','(Excelente nota por su valor geográfico integrado y por ser un motor fundamental del cooperativismo técnico en los Montes Orientales). Fiesta del Aceite de Oliva y de las Jornadas de Cosecha Temprana (noviembre), periodo en el que se abren las bodegas al público para la compra directa y se realizan degustaciones de migas y platos de olla tradicionales. Ruta combinada "Nacimiento de Agua y Olivar Tradicional": Paseo guiado a pie por los senderos que conectan los espectaculares manantiales de Deifontes con los campos de olivos centenarios de la cuenca alta granadina.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29079','oleoturismo','S.C.A. San Isidro de Periana (C/ Cooperativa, S/N) y la ruta paisajística de los Olivos Milenarios del Guaro','(Destaca por la monumentalidad de sus árboles vivos y el enorme valor diferencial de su variedad dulce). Día del Aceite Verdial de Periana (celebrado anualmente a mediados de abril), una fiesta masiva declarada de Singularidad Turística donde se reparten miles de desayunos molineros gratuitos y se organizan catas callejeras. Ruta peatonal por el "Olivar Milenario del Guaro": Paseo a pie guiado por laderas de fuerte pendiente para admirar ejemplares monumentales con perímetros de tronco que superan los 6 metros.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04095','oleoturismo','Almazara de Lubrín Aceites de Oliva Virgen Extra /','(Excelente nota por su fuerte apuesta medioambiental y el diseño impecable de sus salas de degustación). Jornadas del Aceite de Oliva del Valle del Almanzora (noviembre), coincidiendo con la entrada masiva de aceituna en tolva para la obtención de los primeros caldos verdes de la temporada. Ruta a pie por el Olivar del Desierto Alto: Paseo guiado entre parcelas cultivadas sobre terrenos áridos a los pies de la Sierra de los Filabres.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90744','oleoturismo','S.C.A. San Bartolomé Aceite Olibeas (Camino de los Claros, S/N)','(Destaca por el gran volumen y regularidad de sus visitas de grupo y por el imbatible maridaje de su AOVE con el jamón ibérico local). Jornadas del Aceite Nuevo de Beas (noviembre-diciembre), coincidiendo con la apertura de su famoso Belén Viviente, uno de los acontecimientos turísticos más multitudinarios del invierno andaluz. Paseo a pie guiado por el "Olivar de la Campiña de Huelva": Ruta peatonal entre fincas tradicionales de la variedad Verdial de Huévar y Picual, explicando la adaptación del árbol al clima atlántico.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10195','oleoturismo','Almazara Jacoliva / Visitas Trujillo Oleoturismo (Instalaciones y fincas del entorno de la llanura trujillana) y las agencias culturales del casco histórico','(Sobresaliente por la elegancia de su propuesta y por permitir al turista alternar de forma muy fluida la visita a palacios medievales con catas agrícolas de alta gama). Feria Nacional del Queso de Trujillo (mayo), momento álgido donde las operadoras oleícolas locales montan espectáculos de maridaje de AOVE premium extremeño con quesos artesanales ante miles de visitantes. Ruta peatonal de campo combinada: Paseo a pie guiado entre olivares tradicionales integrados en el paisaje de dehesas graníticas de Trujillo.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23087','oleoturismo','Castillo de Torredonjimeno y su','(Destaca de forma única en el inventario por poseer una infraestructura museística preindustrial perfectamente musealizada en el interior de un castillo medieval fortificado). Jornadas Culturales del Tesoro Visigodo y el Aceite Nuevo (fechas variables en otoño), donde se organizan visitas guiadas nocturnas teatralizadas por la almazara antigua y catas dirigidas de los primeros aceites de la cooperativa. Ruta combinada "Castillos y Patrimonio del Aceite": Recorrido histórico guiado por el interior de la fortaleza medieval (S. XII-XIII) que alberga una espectacular almazara de aceite del siglo XVIII restaurada.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23053','oleoturismo','S.C.A. Santísimo Cristo de la Misericordia - AOVE La Quinta Esencia (Camino del Canónigo, S/N) y Aceites La Dehesa (C. Nacimiento, S/ N)','(Excelente nota por su valor histórico cooperativo y la altísima regularidad de la calidad de sus caldos comerciales en ferias nacionales). Jornadas Técnicas del Olivar de Jódar y fiestas del inicio de campaña (noviembre), momento en el que el nuevo consejo rector organiza catas de puertas abiertas para presentar los primeros lotes de La Quinta Esencia. Ruta peatonal por el Olivar Tradicional Centenario: Paseo a pie guiado entre las más de 2.700 hectáreas de cultivo de montaña a los pies del macizo calizo de Mágina.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27050','oleoturismo','Almazara Ouro de Quiroga / Aceite de Quiroga y el Molino Histórico de Centeais (Finca de la familia Valdés)','(Destaca de forma espectacular en el inventario por rescatar y poner en valor las variedades autóctonas gallegas, rompiendo los mitos de la producción del norte peninsular). Mostra do Aceite de Quiroga (celebrada anualmente el fin de semana de Ramos, en marzo o abril), una multitudinaria fiesta declarada de Interés Turístico de Galicia donde el pueblo entero se llena de puestos gastronómicos, catas populares guiadas gratuitas y moliendas públicas en vivo en los molinos históricos. Ruta peatonal por los "Olivares del Sil": Paseo guiado a pie por terrazas e hileras de olivos que crecen en un microclima mediterráneo-atlántico único en los valles del río Sil.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02014','oleoturismo','Almazara Agroisidro / Aceites San José (Ctra. de Jumilla, Km 2) y la Finca El Altiplano de Hellín','(Excelente nota por su valor geográfico fronterizo y por poner en valor variedades locales raras en la base de datos). Jornadas Gastronómicas del Aceite y el Arroz de Calasparra/Hellín (noviembre), un fin de semana festivo donde los restaurantes locales diseñan menús tradicionales regados con los primeros aceites verdes de la temporada. Paseo guiado a pie por los campos de olivar tradicional: Ruta peatonal entre parcelas de secano rústico situadas en la llanura de transición hacia el levante, explicando la resistencia climática del árbol en la comarca.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13023','oleoturismo','Almazara S.C.A. Olivarera del Campo de Calatrava (Ctra. de Almagro, Km 1) y los olivares plantados sobre suelos de origen basáltico y volcánico de la comarca','(Sobresaliente por el extraordinario valor edafológico de sus suelos volcánicos y la perfecta estructura de sus packs de cata y almuerzo manchego). Jornadas de la Cultura del Olivar y el Aceite del Campo de Calatrava (noviembre), periodo donde se abren las bodegas de la cooperativa al público general y se organizan rutas cicloturísticas entre cráteres y olivos centenarios. Ruta peatonal "Olivas y Volcanes": Paseo a pie guiado por las fincas del término municipal para observar la particular morfología de los olivares asentados sobre las tierras oscuras y ricas en minerales procedentes del vulcanismo del Campo de Calatrava.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90449','oleoturismo','S.C.A','(. Jornadas del Olivar y Fiesta del Aceite Fresco de Carcabuey (octubrenoviembre), coincidiendo con los primeros días de molturación en verde y la llegada masiva de sumilleres de todos los continentes para testar los primeros caldos de campaña. Paseo guiado "Senderos de la Hojiblanca de Montaña": Ruta peatonal por el interior del Parque Natural de las Sierras Subbéticas para contemplar el cultivo tradicional en pendientes extremas y el manejo del suelo pedregoso calizo.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30009','oleoturismo','Almazara Valle de Ricote / Aceites de Archena (Paraje del Hurtado, S/N) y la red de acequias históricas de origen andalusí','(Destaca por la belleza singular de su entorno paisajístico fluvial andalusí y por poner en valor la escasa variedad local Cuquillo). Jornadas del Aceite Nuevo y de la Gastronomía del Ricote (noviembre), organizando visitas especiales donde el turista puede disfrutar de catas a ciegas combinadas con la recolección manual lúdica de aceituna. Ruta peatonal "El Olivar de la Vega del Segura": Paseo a pie guiado por las parcelas de regadío tradicional del Valle del Ricote, contemplando olivos centenarios integrados en un paisaje de palmeras y frutales.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90378','oleoturismo','Almazara de Agres Cooperativa Agrícola (C/ de la Font d''Alfafara, S/N) y los olivares abancalados del Parque Natural de la Sierra de Mariola','(Excelente nota por su fuerte apuesta por la recuperación agronómica de variedades autóctonas muy raras de montaña y el gran valor etnográfico de su menú campero de pericana). Jornadas de la Cosecha Tradicional de Montaña (noviembre), periodo donde se abren las líneas de molturación al público y se organizan rutas guiadas de avistamiento botánico entre olivos. Ruta peatonal de montaña "Entre Olivos y Cavas de Nieve": Senderismo guiado a pie por las escarpadas terrazas calizas de la sierra para admirar los olivos tradicionales cultivados a gran altitud.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41068','oleoturismo','Almazara 1881 / Aceites Santa Teresa (Ctra. Lantejuela, Km 1) y los olivares de la monumental Finca Las Valdivias','(Sobresaliente por la excelente organización de sus packs de cata y por permitir al turista alternar de forma fluida el turismo señorial barroco con la oleicultura de alta gama). Jornadas del Aceite Nuevo y de la Tapa de Osuna (noviembre), periodo festivo donde las operadoras oleícolas locales organizan catas a ciegas abiertas al público y los restaurantes diseñan platos regados con los primeros caldos verdes de la campaña. Ruta peatonal por los "Olivares de la Campiña de Osuna": Paseo a pie guiado entre hileras de olivos de la variedad Hojiblanca y Lechín, combinando la interpretación agrícola con el avistamiento de aves esteparias.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16112','oleoturismo','Almazara Pago de la Colina / Olivares de Altomira (Paraje de la Alcarria Conquense) y el patrimonio monumental de la ciudad de Huete','(Excelente nota por poner en valor una de las variedades de aceituna más singulares y resistentes de la meseta norte y por la comodidad de sus actividades familiares). Fiesta del Aceite de la Alcarria Conquense (noviembre-diciembre), un fin de semana festivo donde se abren las líneas de envasado al público general para la compra directa y se organizan catas populares gratuitas. Ruta botánica e histórica "Entre Olivos Alcarreños": Paseo a pie guiado por las parcelas de olivar tradicional de secano situadas en las laderas de la Sierra de Altomira, explicando la adaptación del árbol a la altitud y los rigores térmicos de Cuenca.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44049','oleoturismo','Mas de Flandi (Ctra. de Calaceite a Cretas) y la almazara cooperativa S.C.A. San Isidro de Calaceite','(Sobresaliente por la magnífica preservación de su entorno natural e histórico y la calidad de sus packs de agroturismo bajo reserva). Jornadas del Aceite Nuevo en el Matarraña (noviembre y diciembre), coincidiendo con la molienda de las primeras olivas en verde para extraer caldos limpios con tonos frutados intensos antes del frío invernal. Ruta peatonal por el "Olivar de Piedra Seca del Matarraña": Paseo guiado a pie por terrazas tradicionales integradas en el paisaje medieval, descubriendo muros y refugios de piedra declarados Patrimonio de la Humanidad por la UNESCO.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43123','oleoturismo','Unió Origen - Estació Oleícola de Reus (Ctra. de la Selva del Camp, S/N) y el panel oficial de cata del Baix Camp','(Alta puntuación por la rigurosidad científica de sus talleres de cata y su excelente conectividad con la red de turismo del modernismo de Reus). Fira de l''Oli Nou de Reus (celebrada anualmente en el mes de noviembre en la Plaza de la Llibertat), un gran mercado popular que reúne a productores de toda la comarca para ofrecer catas públicas y degustaciones de pan con aceite nuevo. Tour de Oleoturismo Urbano e Industrial: Recorrido a pie guiado por las naves históricas de almacenamiento y los laboratorios centrales de control de calidad de la gran central oleícola.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','oleoturismo','Dcoop - Museo de la Cultura del Olivar y Sede Central (Ctra. de Córdoba, S/N) y Finca La Torre S.L.U. (Camino de la Torre, S/N, Bobadilla)','(. Jornadas de la Primera Molienda en Verde (mediados de octubre), época en la que las fincas activan sus programas exclusivos para ver la recolección nocturna y la extracción a temperaturas inferiores a 22°C. Paseo guiado a pie por el Olivar Biodinámico y Centenario: Recorrido de campo en Finca La Torre para observar el manejo ecológico estricto, pastoreo ovino integrado y control biológico de plagas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90022','oleoturismo','Can Miquel Guasch Oleoteca Eivissa (Ctra. de San Miguel, Km 12.3) y los olivares tradicionales del norte de la isla','(Sobresaliente por el diseño estético de su oleoteca y por ser la marca pionera que revolucionó la calidad y el embotellado de alta gama en el sector agrícola ibicenco). Jornadas Gastronómicas de Otoño de Ibiza (octubre y noviembre), periodo de plena molienda donde la finca organiza catas comentadas combinadas con maridajes de vinos locales de la tierra de Ibiza.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31165','oleoturismo','Almazara S.C.A. Trujal de Mendavia (Ctra. de Logroño, S/N) y los olivares tradicionales regados por el río Ebro','(Destaca por su imbatible sinergia con la huerta navarra y la perfecta estructuración de sus jornadas de puertas abiertas). Jornadas Gastronómicas del Aceite Nuevo de Mendavia (noviembre-diciembre), organizando catas de invierno y talleres donde los visitantes compran de forma directa los primeros aceites verdes de la temporada sin filtrar. Ruta peatonal por el "Olivar de la Ribera Alta": Paseo a pie guiado por las hileras de las variedades Arbequina y Empeltre, detallando el manejo agrícola en una de las comarcas con más certificaciones de calidad alimentaria de España.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06016','oleoturismo','Almazara Cortijo de l''Alba / Monesterio Oleoturismo (Fincas del entorno de las estribaciones de Sierra Morena) y el Museo del Jamón de Monesterio','(Sobresaliente por su imbatible propuesta lúdica de maridaje de productos ibéricos y la gran accesibilidad de sus rutas de campo). Día del Jamón de Monesterio (septiembre) y jornadas del aceite nuevo (noviembre), momentos donde las operadoras locales activan talleres interactivos de corte, cata y molienda abierta ante miles de visitantes. Ruta peatonal combinado "Dehesa y Olivar de Montaña": Paseo a pie guiado entre hileras de olivos de la variedad Morisca y Picual, combinando la interpretación agrícola con la observación de cerdos ibéricos en montanera.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02004','oleoturismo','Agroecológica de la Sierra de Alcaraz - Aceites Olmo de la Sierra (Ctra. de Horcajo, S/N) y la red de olivares ecológicos de montaña','(Destaca por el altísimo valor de su certificación ecológica estricta de montaña y la comodidad de sus packs de senderismo técnico con almuerzo incluido). Jornadas del Aceite Ecológico y de Montaña de Alcaraz (noviembre), periodo en el que se organizan talleres de campo lúdicos de recogida y catas de los primeros lotes verdes de la temporada. Ruta peatonal "Olivares de Alta Montaña": Paseo a pie guiado por fincas situadas a más de 900 metros de altitud en la Sierra de Alcaraz, explicando los métodos de la agricultura 100% ecológica en climas fríos.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29043','oleoturismo','Almazara AGAMMA Aceites de la Axarquía (Pol. Ind. Industrial de Colmenar, C/ Algatocín, S/N) y las rutas integradas de la cooperativa agroalimentaria local','(Excelente nota por su fantástica propuesta de maridaje tradicional con embutidos de los Montes de Málaga y por la regularidad de sus visitas de grupo). Fiesta del Mosto y de la Chacina de Colmenar (diciembre), momento álgido donde la almazara y los productores locales montan grandes mercados de catas públicas y degustaciones gastronómicas multitudinarias. Ruta de campo "Olivares de los Montes de Málaga": Paseo a pie guiado entre laderas empinadas y bancales calizos para conocer la agricultura del olivar tradicional de la variedad Verdial y Hojiblanca.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25029','oleoturismo','Cooperativa d''Arbeca i Secció de Crèdit (Av. dels Portals, S/N) y los olivares monumentales de la Finca Vilars','(Máxima puntuación provincial por su imbatible valor fundacional e histórico y la excelente estructuración de sus jornadas gastronómicas de invierno). Sesión de cata guiada por sumilleres locales utilizando copas homologadas para puntuar su AOVE premium de recolección temprana de la D.O.P. Les Garrigues. Ruta peatonal "Cuna e Historia de la Arbequina": Paseo a pie guiado por las parcelas donde el Duque de Medinaceli introdujo la aceituna desde Palestina en el siglo XVIII, dando origen al nombre de la variedad "Arbequina" (de Arbeca).','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11034','oleoturismo','Almazara El Molino / Aceites de Setenil (Fincas y cooperativas del entorno de las casas cueva) y el casco histórico bajo el tajo de roca','(Destaca por la belleza singular de su entorno paisajístico y urbano y por la comodidad de combinar rutas de monumentos con oleocultura). Jornadas Gastronómicas del Aceite y el Ibérico de Setenil (noviembre), periodo en el que los bares y restaurantes del municipio diseñan tapas y recetas tradicionales regadas en vivo con el primer aceite nuevo de la campaña. Ruta combinada "Arquitectura y Olivar de Ladera": Paseo a pie guiado que arranca en las famosas calles de las cuevas del sol y de la sombra hacia los campos de olivo tradicional cultivados en pendientes pedregosas a los pies del río Guadalporcún.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90486','oleoturismo','Almazara ecológica Ecoribera / El Lagar del Mudo y el molino preindustrial restaurado del casco urbano','(Sobresaliente por la recuperación agronómica de una variedad única y la excelente combinación de patrimonio paisajístico y arqueología industrial real). Jornadas de Puertas Abiertas de la Molienda de Invierno (diciembre), momento en el que la almazara moderna activa talleres interactivos donde los turistas pueden prensar aceitunas de forma lúdica y embotellar su propio caldo sin filtrar. Ruta peatonal "Entre Cañones y Olivos": Senderismo guiado a pie por los bancales del Parque Natural de Arribes del Duero, explicando el microclima mediterráneo que resguarda a los árboles del frío de la meseta.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45124','oleoturismo','Finca El Tejar /','(Excelente nota por su valor geográfico y la comodidad operativa de sus packs de reserva familiar con almuerzo contundente manchego de cortijo). Jornadas Gastronómicas del Aceite Nuevo de Orgaz (noviembre), periodo festivo donde las operadoras locales activan catas populares gratuitas en el patio y abren los depósitos para la venta directa al público.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32003','oleoturismo','S.C.A. Virgen de Gracia (Ctra. de Belda, S/N) y los olivares tradicionales integrados en el entorno de la Hoz de Marín','(Excelente nota por su alto valor etnográfico integrado y por la comodidad operativa de sus packs de reserva familiar). Jornadas del Aceite de Cosecha Temprana de Archidona (noviembre), un fin de semana festivo donde el municipio organiza mercados de productores locales, catas a ciegas populares gratuitas en la plaza y concursos de cocina. Ruta peatonal "Entre Olivos y Calizas": Paseo a pie guiado por las parcelas de olivar tradicional de ladera que rodean el casco histórico, explicando las técnicas de recolección en terrenos de relieve accidentado.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45010','oleoturismo','Cooperativa Vinícola Ontinyent - Olis de la Vall (Av. del Tèxtil, S/N) y la red de olivares antiguos de la comarca','(Excelente nota por la puesta en valor de variedades autóctonas raras de levante y el gran valor etnográfico de su menú tradicional de almuerzo). Feria de Noviembre de Ontinyent y jornadas de puertas abiertas del trujal (noviembre), periodo donde se abren las líneas de molturación al público general y se organizan catas populares gratuitas. Ruta peatonal por el Olivar Tradicional Central: Paseo guiado a pie por fincas seleccionadas de la comarca para identificar las características del cultivo mediterráneo de secano del interior valenciano.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50230','oleoturismo','Almazara Cooperativa Santa Anastasia (Fincas e instalaciones integradas en el entorno de las Cinco Villas) y el conjunto monumental del Castillo de Sádaba','(Excelente nota por su alto valor etnográfico integrado y por la comodidad de combinar rutas monumentales de castillos con oleocultura). Jornadas del Aceite Nuevo en las Cinco Villas (noviembre y diciembre), periodo festivo donde la cooperativa abre las líneas de envasado al público general para la venta directa al público y organiza catas populares gratuitas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90903','oleoturismo','S.C.C.L. Foment Maialenc (Av. de Lleida, 48) y los olivares tradicionales del sector sur del Segrià','(Sobresaliente por la excelente organización de su feria sectorial y la impecable infraestructura de recepción de su agrotienda gourmet de venta directa). Sesión técnica de cata guiada utilizando copas normalizadas oscuras para aprender a buscar los descriptores dulces bajo el amparo de la D.O.P. Les Garrigues. Ruta peatonal por el paisaje de secano y cabañas: Paseo guiado a pie entre fincas de olivar de la variedad Arbequina, descubriendo las antiguas construcciones de piedra seca utilizadas históricamente por los agricultores locales.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45112','oleoturismo','S.C.A. San Sebastián de Los Navalmorales (Av. de la Constitución, 98) y los olivares tradicionales de secano de la comarca de La Jara','(Excelente nota por su alto valor etnográfico integrado y por poner en valor la pureza del cultivo tradicional de secano en la meseta central). Jornadas del Aceite Nuevo de Los Navalmorales (noviembre), periodo en el que se abren las líneas de envasado al público general para la venta directa de fábrica y se organizan catas populares gratuitas. Ruta peatonal "El Olivar de la Jara": Paseo a pie guiado por las parcelas rústicas situadas en las estribaciones de los Montes de Toledo, explicando la resistencia climática de los árboles ante las heladas invernales.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31251','oleoturismo','Trujal Mendía S.C.A. (Ctra. de Logroño, S/N) y los olivares tradicionales situados en la linde navarro-riojana','(Sobresaliente por la excelente organización de sus packs de cata, su modelo asociativo pionero y el gran valor botánico de salvaguardar su variedad autóctona rústica). Jornadas de la Tostada y el Aceite Nuevo de Viana (enero-febrero), un fin de semana festivo donde el municipio organiza mercados de productores locales, demostraciones gastronómicas y catas populares gratuitas en la calle. Ruta peatonal de campo combinada: Paseo a pie guiado por las hileras de olivos tradicionales que crecen en las terrazas aluviales del río Ebro, explicando el límite septentrional del cultivo de la variedad Arróniz.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25234','oleoturismo','Ecovall - Oli del Pallars (Fincas e instalaciones integradas en la cuenca de Tremp) y los olivares recuperados del Pallars Jussà','(Destaca por la enorme labor botánica de recuperación de variedades olvidadas y la belleza alpina de su entorno paisajístico). Jornadas Gastronómicas del Aceite de Montaña del Pallars (noviembre), coincidiendo con la recolección temprana de las olivas antes de la llegada de las primeras nieves del Pirineo.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03024','oleoturismo','Almazara El Teuladí (Ctra. de Alquería d''Asnar, S/N) y los olivares centenarios de la comarca de El Comtat','(Excelente nota por su fuerte compromiso con las variedades autóctonas raras de levante y el extraordinario valor culinario de su menú campero de pericana). Jornadas de Puertas Abiertas del Trujal y Campaña del Aceite Nuevo (noviembre y diciembre), periodo de plena molturación donde los visitantes pueden presenciar en directo la trituración y adquirir garrafas recién salidas de la bodega. Ruta peatonal por el Olivar Tradicional de la Sierra:. Paseo guiado a pie por pequeñas parcelas abancaladas con muros de piedra seca, explicando el manejo tradicional de secano en las faldas de la Sierra de Mariola.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14025','oleoturismo','S.C.A. San Isidro de Espejo (Ctra. de Montilla, S/N) y el entorno monumental del Castillo de Espejo','(Excelente nota por su imbatible combinación de patrimonio chacinero tradicional y oleocultura en un marco paisajístico imponente). Jornadas de la Matanza Tradicional y el Aceite Nuevo (octubrenoviembre), periodo festivo donde el municipio organiza desfiles, catas populares gratuitas en la plaza central y mercados de productores locales. Ruta peatonal por el "Olivar de la Campiña Alta": Paseo a pie guiado por las hileras de olivos rústicos que se extienden bajo la silueta del castillo ducal, explicando el manejo agronómico del secano en tierras de albarizas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30039','oleoturismo','Almazara El Tendre (Ctra. de Mazarrón, Km 2) y los olivares centenarios de las estribaciones de Sierra Espuña','(Excelente nota por poner en valor la artesanía local asociada a la oleicultura y el gran valor culinario de su menú de almuerzo huertano). Jornadas de Oleoturismo y Campaña del Aceite Nuevo en el Guadalentín (noviembre), periodo donde se abren las líneas de molturación al público general y se organizan catas populares gratuitas en la almazara. Ruta peatonal "Entre Olivos y Alfarería": Paseo guiado a pie por fincas seleccionadas de cultivo tradicional de secano, enlazando la interpretación del árbol con visitas a talleres de artesanos alfareros locales.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23075','oleoturismo','S.C.A. San Ginés y San Isidro - AOVE Castillo de Sabiote (Ctra. del Campillo, S/ N) y el monumental Castillo de Sabiote (siglo XVI)','(Destaca de forma imbatible en el inventario por permitir al turista alternar rutas de arquitectura defensiva militar plateresca con oleocultura de alta gama). Fiestas del Medievo de Sabiote (mayo) y jornadas de la cosecha del aceite nuevo (noviembre), momentos donde los operadores locales montan mercados de época con tabernas populares donde todos los platos tradicionales se riegan con el primer AOVE de campaña. Ruta peatonal "Olivares bajo las Almenas": Paseo guiado a pie por fincas de olivar tradicional que bordean la muralla medieval-renacentista, explicando el manejo agronómico de la comarca de La Loma alta.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13033','oleoturismo','Almazara S.C.A. Santiago Apóstol - Aceite Señorío de Santiago (Av. de la Constitución, S/N) y los olivares tradicionales situados en las estribaciones de Sierra Morena','(Excelente nota por su alto valor etnográfico integrado y por poner en valor la pureza del cultivo tradicional de secano en laderas de media montaña). Jornadas del Aceite Nuevo en el Campo de Montiel (noviembre), periodo en el que se abren las líneas de envasado al público general para la venta directa de fábrica y se organizan catas populares gratuitas. Ruta peatonal "El Olivar de la Meseta Alta": Paseo a pie guiado por las parcelas rústicas del Campo de Montiel, detallando el manejo agrícola y los métodos de conservación del suelo de secano extremo ante las heladas de la meseta central.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18135','oleoturismo','S.C.A. San Francisco de Asís - Aceite Montefrío (Ctra. de Alcalá la Real, S/N)','(Excelente nota por su imbatible combinación de patrimonio paisajístico monumental, su afamada industria del queso de cabra y oleocultura de alta gama). Jornadas Gastronómicas del Aceite Nuevo y el Queso de Montefrío (noviembre), periodo festivo donde las operadoras locales organizan catas populares gratuitas en la plaza central y mercados de productores de la comarca. Ruta peatonal "Olivares entre Peñas": Paseo a pie guiado por las parcelas de olivar tradicional de ladera que se extienden bajo la silueta del imponente tajo y el castillo medieval, explicando el manejo agronómico del secano de montaña.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07027','oleoturismo','Son Naava - Biodynamic Olive Oil (Finca Son Naava, Ctra. Palma-Alcudia) y la histórica Tafona de Son Catiu (Ctra. Inca-Llubí, Km 3.8)','(Máxima puntuación en infraestructuras lúdicas y restauración integrada por la comodidad y el empaque balear de sus degustaciones en el restaurante de la tafona). Jornadas del Aceite de Campaña (octubre-noviembre), coincidiendo con las semanas de molturación en vivo donde los visitantes pueden ver entrar el remolque y comer el pan tostado con el primer hilo de aceite verde esmeralda. Ruta peatonal "Olivares Deméter y Biodinámicos": Paseo a pie guiado por las parcelas de Son Naava, la única finca de Mallorca con certificación 100% Demeter, explicando los ciclos astronómicos y preparados orgánicos en el suelo de la llanura central (Es Raiguer).','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23069','oleoturismo','S.C.A. San Benito (Av. de Andalucía, S/N) y la imponente cisterna romana de Obulco (recurso cultural integrado en las visitas)','(Excelente nota por su imbatible entrelazado de historia arqueológica romana real con la cultura del cultivo tradicional extensivo). Jornadas del Aceite de Campaña y de la Tapa en Porcuna (noviembre), periodo festivo donde se organizan catas populares gratuitas en la calle y la cooperativa abre las bodegas para la venta directa al consumidor. Ruta combinada "Arqueología Subterránea y Olivar de Secano": Paseo guiado a pie por el término municipal que une los espectaculares olivares tradicionales de la campiña baja jiennense con las monumentales ruinas romanas subterráneas de Obulco.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41024','oleoturismo','Basilippo - Oleoescuela y Finca Cobatillas (Ctra. Carmona-El Viso del Alcor, Km 2) y su cortijo señorial andaluz','(. Jornadas de la Cosecha Familiar de Basilippo (octubre), un evento premium bajo reserva donde grupos reducidos de turistas participan en la recolección manual de la aceituna Manzanilla, asisten a su molienda instantánea a 20°C y embotellan su propio caldo exclusivo de la temporada de otoño. Paseo guiado a pie por la "Oleoescuela": Ruta botánica y pedagógica en mitad de la finca, diseñada con senderos interactivos para que niños, familias y adultos descubran las diferencias biológicas de las hojas, troncos y frutos del olivar.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06004','oleoturismo','Almazara Viñaoliva S.C. (Ctra. Santa Marta, S/N) y la red de cooperativas integradas en la llanura de Tierra de Barros','(Sobresaliente por el gran valor didáctico de sus talleres cooperativos y por permitir al viajero unificar de forma fluida el enoturismo con la oleicultura de alta gama). Jornadas del Aceite Nuevo y de la Gastronomía de Barros (noviembre), periodo en el que se abren las líneas de molturación al público y se organizan catas populares gratuitas de los primeros caldos verdes de la campaña.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45061','oleoturismo','Almazara de Escalona Aceites Valdezarza (Ctra. de Nombela, Km 2) y el entorno paisajístico de la vega del río Alberche','(Excelente nota por su valor geográfico y la comodidad operativa de sus packs de reserva familiar con almuerzo contundente de cortijo). Jornadas del Aceite Nuevo del Alberche (noviembre-diciembre), periodo festivo donde la finca organiza catas populares gratuitas y abre sus bodegas para la venta directa al público. Ruta peatonal "Entre Olivos y Encinas": Paseo a pie guiado por las parcelas agrícolas integradas de la finca, explicando los métodos de conservación del suelo manchego frente a los rigores invernales de la meseta norte.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29032','oleoturismo','S.C.A. San Benito (Av. de la Cooperativa, S/N) y los olivares tradicionales de secano de la llanura norte de la provincia','(Excelente nota por su alto valor etnográfico integrado y por la comodidad operativa de sus packs de reserva familiar con venta directa). Feria del Jamón y del Aceite de Campillos (noviembre), un fin de semana festivo de gran afluencia donde la cooperativa y los productores locales montan mercados sectoriales con catas populares gratuitas y demostraciones culinarias en directo. Ruta peatonal por el Olivar Tradicional de Campiña Alta: Paseo guiado a pie por hileras de olivos de gran porte en suelos arcillosos y llanos, explicando el manejo agronómico ante inviernos fríos y veranos secos.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31208','oleoturismo','Almazara de Ribaforada Aceites Artajo / Trujal de la Ribera (Finca San José, Ctra. de Fontellas, Km 4.8)','(Sobresaliente por la excelente organización de sus packs de cata, la limpieza absoluta de sus pasarelas industriales y su imbatible sinergia con la gastronomía de las verduras del Ebro). Jornadas de la Primera Molienda Verde de Ribaforada (octubre), un evento exclusivo bajo reserva donde los turistas asisten en directo a la recogida en campo, observan la molienda a temperaturas inferiores a 21°C y embotellan su propio lote de la temporada otoñal. Ruta peatonal "El Olivar de la Huerta": Paseo a pie guiado por la finca que alberga más de 200 hectáreas de olivar ecológico integrado en las vegas aluviales del río Ebro, explicando el manejo técnico de riego de precisión de la variedad Arbequina.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23056','oleoturismo','S.C.A. La Loperana (Av. de Andalucía, 37) y el entorno defensivo del Castillo de Lopera (siglo XIII)','(Excelente nota por su alto valor etnográfico e histórico integrado y la comodidad de su punto de venta directa de fábrica). Jornadas de Recreación Histórica de Lopera (abril) y Fiesta de la Cosecha Temprana (noviembre), momentos donde el municipio organiza catas populares gratuitas en la calle y la cooperativa abre bodegas para venta directa. Ruta combinada "Guerra Civil, Castillos y Olivar de Campiña": Paseo a pie guiado que entrelaza las visitas a los búnkeres históricos de la contienda con las fincas de olivar de la campiña baja.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90402','oleoturismo','Almazara Olimendros / Aceites de Abanilla (Finca Olimendros, Ctra. de Fortuna, Km 5.5)','(Sobresaliente por el extraordinario valor paisajístico y botánico de su entorno semiárido y por la perfecta estructura de sus packs de cata y almuerzo rural). Fiesta de la Gastronomía y el Aceite Nuevo de Abanilla (noviembre), periodo en el que se abren las líneas de molturación al público general y se organizan catas populares gratuitas en la propia almazara. Ruta peatonal "El Olivar del Oasis": Paseo guiado a pie por las fincas de olivar de regadío controlado que crecen junto a badlands y palmerales, explicando la gestión eficiente del agua en climas desérticos.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29059','oleoturismo','S.C.A. Nuestra Señora del Rosario (Av. del Emigrante, S/N) y fincas tradicionales llanas colindantes con la Reserva Natural Laguna de Fuente de Piedra','(Excelente nota por su valor geográfico integrado y la comodidad operativa de sus packs de reserva familiar con venta directa). Jornadas de Oleoturismo y Naturaleza de Humilladero (noviembre), periodo coincidente con el inicio de la molienda verde y las rutas de observación de aves migratorias en las parcelas agrícolas. Ruta peatonal "Olivas y Flamencos": Paseo guiado a pie por fincas llanas de cultivo integrado, explicando el control biológico de plagas en un entorno de alta sensibilidad ornitológica.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02056','oleoturismo','Almazara S.C.A. San José de Ontur (Av. de la Constitución, S/N) y los olivares tradicionales integrados en la comarca de Campos de Hellín','(Excelente nota por su valor geográfico fronterizo y por poner en valor variedades locales raras en la base de datos). Jornadas Gastronómicas del Aceite Nuevo en Campos de Hellín (noviembre), periodo en el que se abren las líneas de envasado al público general para la venta directa de fábrica y se organizan catas populares gratuitas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90658','oleoturismo','Cooperativa Agrícola de Sóller - Fincas de Fornalutx (Área de influencia norte) y los olivares monumentales de montaña de la Finca Can Det','(Excelente nota por su imbatible valor paisajístico y la magnífica preservación de sus bancales y sistemas preindustriales hidráulicos de montaña). Jornadas de la Oliva de la Sierra de Tramuntana (octubre y noviembre), periodo de plena cosecha manual donde se activan rutas botánicas específicas y los restaurantes del pueblo diseñan menús tradicionales basados en el primer aceite del año. Ruta peatonal "Bancales de Piedra Seca": Senderismo guiado a pie por las escarpadas laderas de montaña de la Sierra de Tramuntana (declarada Patrimonio de la Humanidad por la UNESCO), contemplando olivos monumentales esculpidos en roca caliza de más de 600 años.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41055','oleoturismo','Cortijo El Esparragal Oleoturismo Sevilla y la S.C.A. San Sebastián de Lora del Río','(Excelente nota por su valor arquitectónico y la comodidad operativa de sus packs de reserva familiar con almuerzo de cortijo tradicional andaluz). Jornadas Gastronómicas del Aceite Nuevo en la Vega del Guadalquivir (noviembre), un fin de semana festivo de gran afluencia donde se organizan mercados sectoriales, catas populares gratuitas en el patio y demostraciones culinarias en directo. Ruta peatonal por el "Olivar de la Vega": Paseo a pie guiado por las parcelas de regadío controlado de la vega del Guadalquivir, detallando el manejo técnico de la poda andaluza tradicional.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90514','oleoturismo','Olis de Valdeorras','(Destaca en la base de datos nacional por la magnífica recuperación agronómica de variedades únicas y su perfecta integración con el turismo del vino). Jornadas Gastronómicas de las Olivas Ancestrales y el Vino (noviembre), periodo coincidente con la recolección temprana en verde antes del invierno, ofreciendo catas a ciegas populares gratuitas. Ruta peatonal "Olivas entre Viñedos de Godello": Paseo a pie guiado por las hileras de olivos tradicionales plantados en bancales escarpados, explicando el microclima interior gallego que resguarda a los árboles.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16113','oleoturismo','Almazara S.C.A. Unión de Campesinos de Iniesta - Aceites UCI (Av. de la Constitución, S/N) y la red de olivares tradicionales de secano de La Manchuela','(Excelente nota por su alto valor etnográfico integrado y por la comodidad operativa de sus packs de reserva familiar con venta directa). Jornadas del Aceite Nuevo en La Manchuela Conquense (noviembre), periodo en el que se abren las líneas de envasado al público general para la venta directa de fábrica y se organizan catas populares gratuitas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18102','oleoturismo','S.C.A. San Rogelio (Ctra. de Alomartes, S/N) y el entorno paisajístico de la Sierra de Parapanda','(Excelente nota por su valor histórico y geográfico integrado y la comodidad de su punto de venta directa de fábrica). Fiesta de la Cosecha Temprana y jornadas del aceite nuevo (noviembre), periodo coincidente con el inicio de la molienda verde donde la cooperativa abre las bodegas para la venta directa al público. Ruta peatonal "Olivares de la Frontera Nazarí": Paseo guiado a pie por fincas de olivar tradicional de montaña baja, detallando la herencia agrícola de los sistemas de cultivo en laderas calizas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29089','oleoturismo','S.C.A. Nuestra Señora del Rosario de Teba (Av. de la Constitución, S/N) y los olivares tradicionales del entorno de la Hoz del Chorro','(Excelente nota por su alto valor etnográfico integrado y por la comodidad operativa de sus packs de reserva familiar con venta directa). Feria del Queso Artesano y del Aceite de Teba (octubre), un fin de semana festivo de gran afluencia donde la cooperativa y los productores locales montan mercados sectoriales con catas populares gratuitas. Ruta combinada "Castillos y Olivar de Montaña": Paseo a pie guiado por las parcelas de olivar tradicional de ladera que rodean el Castillo de la Estrella, explicando las técnicas de recolección en terrenos escarpados.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24005','oleoturismo','Oleícola San Eladio S.L. AOVE Casa de l''Agua (Ctra. de la Parrilla, S/N) y los olivares ecológicos integrados en las faldas de la Sierra de Andújar','(Sobresaliente por su imbatible marco de ecoturismo y la impecable vinculación de la gastronomía cinegética de Sierra Morena con sus aceites de autor). Jornadas Técnicas del AOVE Temprano y Caza (octubre y noviembre), periodo de plena molturación en verde donde la almazara organiza catas a ciegas populares y talleres de cocina en vivo. Ruta peatonal "Olivas entre Lince e Higuera": Senderismo guiado a pie por parcelas agrícolas ecológicas que colindan con el Parque Natural, combinando las explicaciones sobre la poda tradicional con el avistamiento de avifauna y fauna protegida.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28180','oleoturismo','Recespaña S.C.A. /','(Excelente nota por su alto valor cooperativo y por la comodidad de combinar rutas de monumentos históricos con oleocultura de alta gama). Fiesta del Aceite de Oliva de la Comunidad de Madrid y jornadas del aceite nuevo (noviembre y diciembre), periodo festivo donde la cooperativa abre las líneas de envasado al público general para la venta directa al público y organiza catas populares gratuitas en el patio central. Ruta peatonal por el Olivar Tradicional de la Alcarria Madrileña: Paseo guiado a pie por las fincas del término municipal para observar la adaptación de los árboles rústicos de secano ante los rigores invernales de la meseta central.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17128','oleoturismo','Empordàlia S.C.C.L. / Celler i','(Sobresaliente por fusionar de forma interactiva enoturismo de autor y oleoturismo patrimonial en una de las tiendas gastronómicas más potentes de Cataluña). Festa de l''Oli Nou (celebrada anualmente entre finales de noviembre y principios de diciembre), un fin de semana festivo con catas populares gratuitas directas de los pozuelos, desayunos de pagès multitudinarios y música tradicional en el patio. Ruta peatonal "Olivos de Piedra y Tramuntana": Paseo guiado a pie por parcelas tradicionales con suelos pizarrosos y terrazas de piedra seca, explicando el azote biomecánico del viento del norte sobre las ramas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17010','oleoturismo','S.C.A. Santa Marina de Fernán Núñez (Ctra. de San Sebastian, S/N) y los olivares de la llanura de la Campiña Sur baja','(Excelente nota por su alto valor cooperativo integrado y la gran comodidad de su punto de venta directa de fábrica). Jornadas Técnicas del Olivar y Fiesta de la Cosecha Verde (noviembre), periodo donde el municipio organiza catas populares y rutas cicloturísticas entre olivares, y la cooperativa abre bodegas para la venta directa al público.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10035','oleoturismo','Cooperativa del Campo de Cabezuela del Valle (Av. de la Constitución, S/N) e integradores locales del Valle del Jerte','(Excelente nota por poner en valor la producción agraria heroica de montaña en pendientes extremas y el encanto rústico de su menú de campo). Jornadas de la Cosecha y las Castañas en el Jerte (noviembre), periodo donde el municipio organiza rutas senderistas y catas populares gratuitas en la calle con el primer aceite verde de la campaña recién salido del decánter.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41016','oleoturismo','Hacienda San José Oleotour Aljarafe (Ctra. Aznalcázar-Bollullos, Km 3.5)','(Máxima puntuación provincial por su espectacular patrimonio arquitectónico barroco y la perfecta estructura lúdica de sus talleres enológicos y oleícolas integrados). Jornadas de la Recolección del Aljarafe (septiembre-octubre), época coincidente con el "verdeo" (recogida de la aceituna de mesa a mano mediante el método del "ordeño" tradicional) donde se organizan gincanas familiares y almuerzos camperos. Ruta peatonal "El Olivar de la Viga": Paseo a pie guiado por la imponente finca señorial del siglo XVIII, descubriendo sus campos de olivos de la variedad Gordal y Manzanilla Sevillana adscritos a producción sostenible.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50153','oleoturismo','Almazara Cooperativa Santo Cristo de Magallón - Aceite Pagos del Moncayo (Ctra. de Borja, S/N) y la red de olivares tradicionales que crecen bajo la influencia climática del Moncayo','(Excelente nota por fusionar de forma interactiva la cultura del vino y el aceite en una misma cooperativa y por la comodidad operativa de sus packs de reserva familiar). Jornadas Gastronómicas del Aceite Nuevo en el Campo de Borja (noviembre y diciembre), periodo festivo donde la cooperativa abre las líneas de envasado al público general para la venta directa de fábrica y organiza catas populares gratuitas. Ruta peatonal "Olivas y Viñas del Moncayo": Paseo a pie guiado por las parcelas rústicas de secano, detallando el manejo agrícola y los métodos de prepoda invernal para resistir las heladas y el cierzo.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06019','oleoturismo','Almazara de Olivenza Elosúa / Pago de Los Baldíos (Fincas e instalaciones integradas en el entorno fronterizo del Guadiana) y los olivares tradicionales del término municipal','(Sobresaliente por el extraordinario valor etnográfico de su propuesta fronteriza y por la perfecta estructura de sus packs de cata y almuerzo de cortijo extremeño). Jornadas Gastronómicas del Aceite Nuevo y la Caza en la Comarca de Olivenza (noviembre), periodo coincidente con la recolección temprana en verde antes del invierno, ofreciendo catas a ciegas populares gratuitas. Ruta peatonal "Olivas de la Raya Fronteriza": Paseo a pie guiado por las fincas del término municipal para observar la particular morfología de los olivares asentados sobre las dehesas extremeñas colindantes con Portugal, combinando la interpretación agrícola con el avistamiento de aves.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16175','oleoturismo','Almazara S.C.A. San Isidro de Quintanar del Rey (Av. de la Constitución, S/N) y las explotaciones integradas en las llanuras de la Manchuela Conquense','(Excelente nota por su alto valor cooperativo integrado y por la comodidad operativa de sus packs de reserva familiar con venta directa de fábrica). Sesión de cata didáctica guiada por técnicos locales utilizando copas homologadas para aprender a registrar y catalogar los descriptores verdes de la variedad Cornicabra. Ruta peatonal "El Olivar de Secano Extremo": Paseo guiado a pie por parcelas agrícolas de la comarca, detallando la resistencia climática de los árboles y los métodos tradicionales de poda castellana ante las heladas de la meseta central.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29042','oleoturismo','Almazara Aceites Mueloliva / Molino Cooperativa de Coín (Ctra. de Cártama, S/N) y los olivares tradicionales regados por los manantiales de la comarca','(Sobresaliente por poner en valor la aceituna de mesa y de almazara local de doble aptitud y por la perfecta estructuración de sus almuerzos tradicionales en el porche). Jornadas de Oleoturismo y de la Naranja de Coín (octubre y noviembre), periodo coincidente con el inicio de la molturación en verde y la llegada masiva de visitantes para degustar el primer aceite nuevo de la campaña. Ruta peatonal "El Olivar del Valle del Guadalhorce": Paseo a pie guiado por las fincas del término municipal para observar la morfología de los olivos tradicionales que crecen integrados en un paisaje de huertas de cítricos y frutales.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05240','oleoturismo','Almazara Valle del Tiétar Aceite Sierra de Gredos (Ctra. de Madrid, S/N) y los olivares abancalados de la vertiente sur del macizo de Gredos','(Destaca por la espectacularidad de su paisaje de montaña, su fuerte enfoque artesanal y el encanto rústico de su propuesta gastronómica). Jornadas de la Tostada y el Aceite Nuevo de Gredos (noviembre y diciembre), organizando visitas especiales donde el turista puede embotellar directamente su propio AOVE verde sin filtrar directo de la prensa mecánica continua. Ruta peatonal "Olivos bajo el Granito": Paseo a pie guiado por terrazas tradicionales resguardadas del norte, explicando el manejo de suelos graníticos y el microclima que permite el cultivo oleícola en Ávila.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10096','oleoturismo','Almazara Cooperativa de Hervás - Aceite Valle del Ambroz (Av. de la Constitución, S/N) y los olivares tradicionales de montaña integrados con castañares ancestrales','(Sobresaliente por su imbatible combinación de patrimonio paisajístico y urbano y por la comodidad de combinar rutas de monumentos con oleocultura). Sesión de cata didáctica guiada por técnicos locales utilizando copas homologadas para aprender a registrar y catalogar los descriptores verdes de la variedad Manzanilla Cacereña, bajo el amparo de la D.O.P. Gata-Hurdes. Ruta peatonal "Entre Olivos y Castaños": Paseo a pie guiado por las características terrazas escarpadas del valle, observando cómo convive el olivar de montaña con los bosques del Valle del Ambroz.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23035','oleoturismo','S.C.A. San Juan Bautista (Ctra. de Jaén, S/N) y las fincas de olivar tradicional de la llanura metropolitana','(Excelente nota por su alto valor cooperativo integrado y la gran comodidad de su punto de venta directa de fábrica con precios de origen). Jornadas del Aceite Nuevo en la Campiña Metropolitana (noviembre), periodo en el que se abren las líneas de envasado al público general para la venta directa al consumidor y se organizan catas populares gratuitas. Ruta peatonal "Caminos de la Picual": Paseo a pie guiado por las hileras de olivos tradicionales de secano de la campiña baja, detallando las labores agrícolas estacionales de desvareto y poda.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44246','oleoturismo','Almazara del Matarraña Aceites Amposta (Ctra. de Tortosa, S/N) y la red de olivares tradicionales que crecen integrados en el paisaje monumental del río Matarraña','(Sobresaliente por la excelente organización de sus packs de cata, la belleza de su entorno paisajístico y la impecable calidad de su propuesta culinaria rústica). Jornadas Gastronómicas del Aceite Nuevo en el Matarraña (noviembre y diciembre), periodo festivo donde la cooperativa abre las líneas de envasado al público general para la venta directa de fábrica y organiza catas populares gratuitas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06014','oleoturismo','Almazara de Jerez S.C.A. San Isidro (Ctra. de Zafra, S/N) y los olivares tradicionales integrados en las dehesas de la Sierra Suroeste','(Sobresaliente por poner en valor la variedad autóctona extremeña Morisca y por la magnífica estructuración de sus maridajes con el cerdo ibérico de bellota local). Salón del Jamón Ibérico y del Aceite de Jerez de los Caballeros (mayo), periodo de máxima afluencia donde la cooperativa y los productores locales organizan grandes mercados de catas públicas, demostraciones de corte a cuchillo y degustaciones gastronómicas multitudinarias. Ruta peatonal "Olivos de la Orden del Temple": Paseo a pie guiado por fincas tradicionales de secano de la variedad Morisca, explicando cómo convive el olivar de montaña media con el ecosistema de la dehesa ibérica y los cerdos en montanera.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05241','oleoturismo','Almazara de El Tiemblo Valle de Iruelas / Aceite Alberche (Ctra. de Toledo, S/N) y los olivares de ladera situados en el entorno de la Reserva Natural del Valle de Iruelas','(Excelente nota por su fuerte compromiso con las variedades de alta montaña en pendientes extremas y el extraordinario valor paisajístico de su entorno botánico). Jornadas del Aceite Nuevo de Montaña del Alberche (noviembre y diciembre), periodo de plena molturación en verde donde la almazara abre las bodegas para la venta directa al consumidor de garrafas recién salidas del decánter sin filtrar. Ruta peatonal "Olivas entre Castaños de Gredos": Paseo a pie guiado por las características terrazas escarpadas que miran al embalse de El Burguillo, observando el manejo tradicional de secano de montaña en suelos graníticos y la resistencia climática ante los inviernos de la meseta norte.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23074','oleoturismo','S.C.A. Nuestra Señora de la Asunción (Ctra. Úbeda-Linares, Km 5) y los olivares tradicionales adscritos a la D.O.P. Aceite de Jaén','(Excelente nota por su alto valor cooperativo integrado y la gran comodidad de su punto de venta directa de fábrica con precios de origen). Jornadas Gastronómicas del Aceite Nuevo de Rus (noviembre), periodo en el que se abren las líneas de envasado al público general para la venta directa al consumidor y se organizan catas populares gratuitas en el patio central de la cooperativa. Ruta peatonal por el "Olivar Histórico de los Pozos": Paseo a pie guiado por las parcelas del término municipal, descubriendo el característico paisaje agrario de Rus jalonado por antiguas construcciones de piedra e hipogeos.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25119','oleoturismo','S.C.C.L. Degustus Cooperativa de Juneda (C/ de Prat de la Riba, S/N) y los olivares tradicionales regados de forma controlada por los canales del Urgell','(Sobresaliente por la excelente organización de sus packs de oleoturismo y la impecable infraestructura de recepción de su agrotienda gourmet de venta directa). Sesión técnica de cata guiada utilizando copas de cata oscuras homologadas para aprender a buscar los descriptores dulces bajo el amparo de la D.O.P. Les Garrigues. Ruta peatonal por el paisaje del canal y olivar: Paseo guiado a pie entre fincas de olivar de la variedad Arbequina, descubriendo la ingeniería del agua de la comarca y las antiguas construcciones de piedra seca.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29091','oleoturismo','Almazara de Torrox Aceites El Molino (C/ Almedina, S/N) y las plantaciones tradicionales de olivar en bancales costeros sobre el mar Mediterráneo','(Excelente nota por su microclima y por el extraordinario valor culinario de unificar en su menú campero el aceite dulce con los cultivos tropicales locales). Día de las Migas de Torrox (celebrado anualmente el último domingo antes de Navidad, en diciembre), una fiesta masiva declarada de Interés Turístico Nacional de Andalucía donde se reparten miles de raciones gratuitas regadas en vivo con el aceite Verdial de la almazara. Ruta peatonal "Olivos de Sal y Costa": Paseo a pie guiado por las escarpadas laderas expuestas a las brisas marinas de la Axarquía costera, explicando la adaptación del árbol a suelos pizarrosos y climas subtropicales.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14041','oleoturismo','S.C.A','(Excelente nota por su alto valor cooperativo integrado y la gran comodidad operativa de sus packs de reserva familiar con venta directa de fábrica a precio de origen). Jornadas Gastronómicas del Aceite Nuevo en la Campiña Alta (noviembre-diciembre), periodo coincidente con el inicio de la molturación en verde donde la cooperativa abre las bodegas al público general y se organizan catas populares gratuitas en el patio central. Ruta peatonal por el Olivar del Castillo: Paseo guiado a pie por hileras de olivos de gran porte que se extienden bajo la silueta monumental del Castillo de Montemayor, detallando el manejo de las cubiertas vegetales en los secanos de campiña alta.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12036','oleoturismo','Olis lo Canet S.L. (C/ Font de la Roca, S/N) y la red de Rutas de Olivos Milenarios señalizada por el Ayuntamiento','(Sobresaliente por la excelente organización de sus senderos botánicos autoguiados y guiados y por el altísimo valor de sus monovarietales de la variedad Farga). Jornadas de Oleoturismo y Patrimonio Vivo (noviembre), periodo coincidente con la recolección temprana de los frutos de los árboles monumentales, donde se organizan talleres lúdicos de recogida manual con lienzos tradicionales. Ruta peatonal "El Mar de Olivos de la Farga": Senderismo guiado a pie por parcelas que albergan algunos de los ejemplares de la variedad Farga más monumentales y antiguos de Europa (árboles catalogados con perímetros de tronco superiores a los 7 metros).','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24013','oleoturismo','S.C.A. San Juan de la Cruz - Aceite Sierra de Segura (Av. del Mercado, S/N) y los olivares tradicionales de alta pendiente que miran al Guadalquivir','(Excelente nota por su alto valor cooperativo integrado y la gran comodidad operativa de sus packs de reserva familiar con venta directa de fábrica). Jornadas Técnicas del Aceite Nuevo en la Sierra de Segura (noviembre), periodo en el que se abren las líneas de envasado al público general para la venta directa al consumidor de garrafas recién salidas del decánter sin filtrar. Ruta peatonal de Campo y Sierra: Paseo guiado a pie por fincas situadas a altitudes superiores a los 800 metros, explicando las técnicas tradicionales de recolección manual en pendientes pronunciadas e inaccesibles para paraguas mecánicos.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90289','oleoturismo','Almazara Cooperativa San José de Albalate (Ctra. de Andorra, S/N) y la red de olivares tradicionales que crecen en las terrazas fluviales del río Martín','(Excelente nota por su alto valor etnográfico integrado y la gran comodidad de su punto de venta directa de fábrica con precios de origen). Jornadas del Aceite Nuevo en el Bajo Martín (noviembre-diciembre), periodo coincidente con el inicio de la molturación en verde donde la cooperativa abre las bodegas al público general y se organizan catas populares gratuitas en el patio central.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29093','oleoturismo','Almazara de Abdalajís Aceites El Molino (C/ Real, S/N) y los olivares tradicionales de alta pendiente que miran a la Sierra de la Huma','(Excelente nota por su microclima de montaña y por la perfecta estructuración de sus packs de agroturismo bajo reserva). Jornadas de Oleoturismo y Aventura de Abdalajís (noviembre), periodo coincidente con el inicio de la molienda verde y las rutas de senderismo botánico en las parcelas agrícolas de alta pendiente. Ruta peatonal de Campo y Vuelo: Paseo guiado a pie por fincas de olivar tradicional de ladera situadas a gran altitud, explicando las técnicas tradicionales de recolección manual en pendientes pronunciadas e inaccesibles para paraguas mecánicos.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41087','oleoturismo','Hacienda Benazuza /','(Sobresaliente por el extraordinario valor arquitectónico de sus haciendas históricas y por la impecable estructura lúdica de sus talleres sensoriales). Jornadas del "Verdeo" Tradicional (septiembre y octubre), periodo coincidente con la recogida a mano de la aceituna mediante el método de ordeño, donde se organizan talleres lúdicos de aliño tradicional ante los turistas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24006','oleoturismo','S.C.A. San Bonoso y San Maximiano - AOVE Urgapa (Ctra. de Andújar, S/N) y la ruta cultural de la cripta del Barón de Velasco','(Excelente nota por su alto valor histórico integrado y por la comodidad de su punto de venta directa de fábrica con precios de origen). Fiestas de los Santos (agosto, vertiente histórica) y las jornadas de la cosecha del aceite nuevo (noviembre), periodo donde el municipio organiza catas populares y la cooperativa abre las bodegas para la venta directa al público. Ruta combinada "Historia de Reinos y Olivar Extensivo": Paseo a pie guiado que enlaza el patrimonio arqueológico andalusí y templario de la ciudad con las inmensas fincas de olivar de campiña baja.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10121','oleoturismo','S.C.A. San Isidro de Miajadas - Aceites Miajadas (Av. de Trujillo, S/N) y las explotaciones integradas de olivar tradicional de la llanura trujillana-miajadense','(Excelente nota por su alto valor cooperativo integrado y la gran comodidad operativa de sus packs de reserva familiar con venta directa). Jornadas del Aceite Nuevo y de las Migas en Miajadas (noviembre), periodo en el que se abren las líneas de envasado al público general para la venta directa al consumidor y se organizan catas populares gratuitas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90434','oleoturismo','S.C.A. Santo Cristo de Alfarnate - Aceite de los Pirineos del Sur (Av. de la Constitución, S/N) y los olivares tradicionales colgados en terrazas calizas a más de 800 metros de altitud','(Sobresaliente por su microclima de montaña extrema y por la perfecta estructuración de sus almuerzos tradicionales en el porche). Jornadas de Oleoturismo y de la Cosecha de Alta Montaña en Alfarnate (noviembre), periodo coincidente con el inicio de la molienda verde y las rutas de senderismo botánico en las parcelas agrícolas de alta pendiente. Ruta peatonal "Olivas de los Pirineos de la Axarquía": Senderismo guiado a pie por las escarpadas laderas calizas de montaña alta, contemplando olivos tradicionales esculpidos en roca de más de 500 años y explicando las técnicas de recolección en pendientes extremas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24012','oleoturismo','S.C.A. San Isidro - AOVE Oro de Baños (Av. de las Regiones, S/N) y el monumental Castillo de Bury Al-Hammam (siglo X)','(Sobresaliente por permitir al turista alternar rutas de arquitectura militar califal con la oleocultura de alta montaña de Sierra Morena). . Ruta combinada "Fortalezas Omeyas y Olivar de Sierra": Recorrido a pie guiado que conecta los olivares cultivados en suelos pizarrosos con una de las fortalezas califales mejor conservadas de Europa.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23059','oleoturismo','S.C.A. San Julián (Ctra. del Balneario, S/N) y el entorno paisajístico del histórico Balneario de Marmolejo','(Excelente nota por su alto valor cooperativo integrado y la gran comodidad de combinar oleocultura y turismo de bienestar). 🏢 COMUNIDAD AUTÓNOMA: ANDALUCÍA.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14017','oleoturismo','S.C.A. Agro-Olivarera de La Carlota (Av. de la Paz, S/N) y los olivares tradicionales plantados en los llanos de las Nuevas Poblaciones','(Excelente nota por su alto valor etnográfico integrado y la comodidad de su punto de venta directa de fábrica).','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14033','oleoturismo','Almazara de Guadalcázar - Aceites El Henazar (Fincas e instalaciones integradas en el entorno del monte y la campiña baja) y la Vía Verde de la Campiña','(Excelente nota por la puesta en valor del agroturismo cicloturista y la gran comodidad operativa de sus packs de almuerzo tradicional). 🏢 COMUNIDAD AUTÓNOMA: COMUNIDAD DE. . Ruta combinada "Vía Verde y Olivar Tradicional": Paseo a pie o cicloturista guiado por los senderos del antiguo trazado ferroviario, cruzando olivares cultivados en llanuras profundas de albarizas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28072','oleoturismo','Almazara Ecológica de la Sierra de Madrid / Fincas de Hoyo y los olivares de alta montaña colgados en el Parque Regional de la Cuenca Alta del Manzanares','(Excelente nota por su fuerte compromiso con las producciones 100% ecológicas en el límite de altitud central peninsular y su imbatible menú rústico de Guadarrama). 🏢 COMUNIDAD AUTÓNOMA: CASTILLA-LA.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45121','oleoturismo','Almazara S.C.A. Nuestra Señora de los Remedios de Ocaña (Av. del Parque, S/N) y la red de olivares tradicionales que crecen en las llanuras esteparias de la Mesa de Ocaña','(Excelente nota por su valor geográfico y la gran comodidad operativa de sus packs de reserva familiar con venta directa de fábrica a precio de origen). 🏢 COMUNIDAD AUTÓNOMA: ARAGÓN. . Ruta peatonal "El Olivar de la Estepa Manchega": Paseo a pie guiado por las parcelas rústicas de secano extremo, detallando el manejo de las cubiertas vegetales y la resistencia climática de los árboles ante las heladas de la meseta.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44172','oleoturismo','Almazara Social de Oliete - Apadrinaunolivo.org (C/ Mayor, S/N) y el espectacular cañón de la Sima de San Pedro (recurso natural integrado)','(Sobresaliente por el extraordinario valor ético, social y medioambiental de su propuesta y por permitir al turista participar de forma activa en la reactivación de un ecosistema agrario milenario). 📝 ANÁLISIS DE LA IMPORTANCIA GASTRONÓMICA E INTEGRACIÓN TURÍSTICA DE LOS BLOQUES SINTETIZADOS La adición de estos cinco macro-bloques consolida la estructura global del inventario al fijar las variantes de mayor resistencia climática y geológica del país: 1. Sesión didáctica con copas de cata homologadas oscuras para descubrir y registrar los atributos dulces del aceite Empeltre y la rara variedad autóctona local Royal de Alloza. Ruta peatonal de Campo y Sostenibilidad: Paseo guiado a pie por los olivares tradicionales recuperados de la variedad Empeltre, explicando el modelo de custodia del territorio, apadrinamiento tecnológico y lucha contra la despoblación rural.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43155','oleoturismo','Cooperativa Soldebre S.C.C.L. (Av. de la Generalitat, S/N) y los olivares del delta interior del Ebro','(Sobresaliente por poner en valor las variedades autóctonas del delta interior y la perfecta organización de sus visitas de grupo).','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43071','oleoturismo','Identitat Extra Virgin Olive Oil (C/ de la Comanda, S/N) y el majestuoso olivo milenario "Lo Parot" (recurso botánico integrado)','(. . Ruta botánica e histórica "El Olivo de Picasso": Paseo a pie guiado por las hileras de olivos tradicionales que inspiraron al pintor en su etapa cubista, visitando el árbol monumental "Lo Parot" (con más de 1.500 años de antigüedad).','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30022','oleoturismo','Almazara Casa de la Ermita - Oli-Ermita / Aceites Silvano S.L. (Paraje de la Estacada, S/N) y los olivares ecológicos integrados en tierras de secano rústico','(Excelente nota por fusionar de forma interactiva la cultura del vino y el aceite en una misma zona y por la perfecta estructura de sus packs de cata y almuerzo rural). . Ruta peatonal "Olivas y Monastrell": Paseo a pie guiado por fincas que combinan en perfecta simetría hileras de olivo tradicional con viñedos viejos de uva Monastrell, explicando el manejo agrícola en climas áridos.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30043','oleoturismo','Almazara Deortegas S.L. - Finca Los Charcos (Paraje Los Charcos, Ctra. de Yecla a Pinoso) y los olivares 100% ecológicos de secano','(Sobresaliente por el diseño estético de su almazara bioclimática, el enorme palmarés ecológico de sus marcas y la calidad de su atención multilingüe). 🏢 COMUNIDAD AUTÓNOMA: NAVARRA. . Ruta peatonal "El Olivar del Altiplano Ecológico": Paseo guiado a pie por fincas de cultivo biológico extremo de baja pluviometría, explicando las técnicas de conservación del suelo y el manejo integrado de plagas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31152','oleoturismo','Almazara de Lerín Aceites Erro / Trujal de Lerín (Ctra. de Cárcar, S/N) y los olivares tradicionales regados de forma controlada por el río Ega','(Excelente nota por su alto valor cooperativo integrado, por la puesta en valor de su variedad autóctona rústica y por la comodidad operativa de sus packs de reserva familiar con venta directa). 🏢 COMUNIDAD AUTÓNOMA: ANDALUCÍA. . Ruta peatonal "El Olivar del Ega": Paseo a pie guiado por las hileras de las variedades Arróniz y Empeltre, detallando el manejo agrícola y los métodos de prepoda invernal para resistir los vientos del norte peninsular.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23058','oleoturismo','Oleícola San José S.C.A. San José (Av. de San José, S/N) y los olivares de alta montaña colgados en las laderas de Sierra Mágina','(Excelente nota por su alto valor cooperativo integrado y la gran comodidad de su punto de venta directa de fábrica con aceites de sierra premium).','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24086','oleoturismo','S.C.A. Santa Isabel de Torres - AOVE Señorío de Torres (Av. de Jaén, S/N) y los olivares tradicionales colgados en terrazas calizas a los pies del pico Mágina','(Sobresaliente por su microclima de montaña extrema y por la perfecta estructuración de sus almuerzos tradicionales en el porche). CONTROL DE LA VENTANA DE CONTEXTO Y AVANCE ALFABÉTICO: La base de datos nacional de servicios de reserva turística real ha sido expandida masivamente de forma unificada mediante seis bloques estructurales. Elija el siguiente paso del plan de ruta estratégico: • Continuar con el Siguiente Grupo Masivo de Bloques: Desplegar de forma simultánea municipios de Ávila (Mombeltrán), Cádiz (Zahara de la Sierra), Málaga (Campillos ampliado) y Zaragoza (Belchite ampliado).','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05132','oleoturismo','S.C.A. San Pedro Bautista (Av. de lares, S/N) y los olivares en terrazas de piedra que rodean el Castillo de los Duques de Alburquerque','(Destaca por el imbatible empaque paisajístico que ofrece su castillo medieval rodeado de olivos e higueras, sumado a la rusticidad de su propuesta). 🏢 COMUNIDAD AUTÓNOMA: ANDALUCÍA. . Ruta peatonal "Olivas del Barranco de las Cinco Villas": Paseo guiado a pie por las laderas graníticas de la vertiente sur de Gredos, analizando cómo el microclima del valle protege el olivar tradicional frente a las heladas castellanas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90739','oleoturismo','Almazara Oleum Viride (Ctra. de Grazalema, Km 2.5) y las fincas tradicionales que cuelgan sobre el embalse de Zahara-El Gastor','(. . Ruta peatonal "Olivares entre Pinsapos": Paseo a pie guiado por las parcelas de olivar tradicional cultivadas en pendientes extremas calcáreas, bajo el régimen de lluvias más elevado de la península.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29088','oleoturismo','S.C.A. Agro-Olivarera San Isidro (Av. de la Constitución, S/N) y los olivares de secano extensivo de la llanura norte provincial','(Excelente nota por su alto valor cooperativo integrado y la gran comodidad operativa de su punto de venta directa de fábrica). 🏢 COMUNIDAD AUTÓNOMA: ARAGÓN. . Ruta peatonal por el Olivar Tradicional de Campiña Alta: Paseo guiado a pie por hileras de olivos de la variedad Hojiblanca, analizando el manejo mecánico de suelos y las podas estacionales.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90149','oleoturismo','Almazara Cooperativa Cosanse (Ctra. de Zaragoza, S/N) y la red de olivares tradicionales que crecen integrados en las vegas de frutales de Valdejalón','(Excelente nota por la robustez industrial de sus instalaciones, la claridad didáctica de sus explicaciones de molienda y la comodidad operativa de su agrotienda de venta directa). CONTROL DE LA VENTANA DE CONTEXTO Y AVANCE ALFABÉTICO: La base de datos nacional de servicios de reserva turística real ha sido expandida masivamente de forma unificada mediante cuatro bloques estructurales. Elija el siguiente paso del plan de ruta estratégico: • Continuar con el Siguiente Grupo Masivo de Bloques: Desplegar de forma simultánea municipios de Córdoba (Baena ampliado), Sevilla (Écija ampliado), Toledo (Mora ampliado) y Jaén (Alcaudete). . Ruta peatonal "Olivas de Valdejalón": Paseo a pie guiado por las parcelas rústicas de secano, detallando el manejo agrícola y los métodos de prepoda invernal para resistir los vientos del cierzo.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10124','oleoturismo','Jacoliva -','(Sobresaliente por el gran valor didáctico de sus talleres cooperativos y por permitir al viajero unificar el turismo arqueológico con la oleicultura de alta gama). 🏢 COMUNIDAD AUTÓNOMA: EXTREMADURA. . Ruta peatonal por el "Olivar de Tierras de Granadilla": Paseo a pie guiado entre hileras de la variedad Manzanilla Cacereña, explicando la gestión biológica y la protección del suelo granítico frente a las escorrentías.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06002','oleoturismo','Almazara Pago de los Baldíos de San Carlos S.L. (Finca San Carlos, Ctra. de Olivenza) y los olivares centenarios de la comarca de Olivenza-Llanos de Olivenza','(.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30020','oleoturismo','Almazara Olimendros / Finca Olimendros (Ctra. de Fortuna a Abanilla, Km 5.5) y el patrimonio hídrico tradicional de la comarca oriental','(Excelente nota por poner en valor la variedad autóctona Cuquillo y por la perfecta estructura de sus packs de cata combinados con turismo de relax). 🏢 COMUNIDAD AUTÓNOMA: ANDALUCÍA. . Ruta peatonal "El Olivar de la Tierra Seca": Paseo a pie guiado por las parcelas de olivar ecológico de regadío controlado que crecen junto a paisajes áridos, detallando la gestión eficiente del agua mediante goteo inteligente de precisión.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29055','oleoturismo','S.C.A. Agro-Olivarera de Fuente de Piedra (Av. de Andalucía, S/N) y las fincas tradicionales llanas colindantes con la Reserva Natural de la Laguna de Fuente de Piedra','(Excelente nota por su valor geográfico integrado y la comodidad operativa de sus packs de reserva familiar con venta directa de fábrica). CONTROL DE LA VENTANA DE CONTEXTO Y AVANCE ALFABÉTICO: La base de datos nacional ha incorporado cuatro bloques estratégicos de alta densidad y empresas reales.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04026','oleoturismo','Almazara de Sorbas SAT Los Alunados y el Paraje Natural Karst en Yesos de Sorbas','(Excelente nota por su valor geográfico integrado y la comodidad de combinar geología espectacular con oleocultura). 🏢 COMUNIDAD AUTÓNOMA: ANDALUCÍA. . Ruta peatonal "Olivas sobre Cristal de Yeso": Paseo a pie guiado por las parcelas agrícolas del entorno desértico, explicando la adaptación del olivo tradicional de la variedad Picual y Arbequina a suelos yesosos extremos.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41095','oleoturismo','Hacienda La Indiana y la S.C.A. Olivarera de Utrera','(Sobresaliente por el extraordinario valor arquitectónico de sus haciendas históricas y por la impecable estructura logística de sus visitas de grupo). 🏢 COMUNIDAD AUTÓNOMA: ANDALUCÍA. . Ruta peatonal por el Olivar Histórico de Campiña: Paseo guiado a pie por majestuosas fincas de la comarca, descubriendo olivares tradicionales de las variedades Gordal Sevillana y Manzanilla, conviviendo con patios andaluces barrocos.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17006','oleoturismo','Almazara de la S.C.A. Olivarera del Egabro (Av. de la Constitución, S/N) y los olivares centenarios de montaña integrados en el Parque Natural de las Sierras Subbéticas','(Excelente nota por su microclima de montaña extrema y por la perfecta estructuración de sus almuerzos tradicionales en el porche). 🏢 COMUNIDAD AUTÓNOMA: CASTILLA-LA. . Ruta peatonal "Entre Olivos y Calizas Egabrenses": Senderismo guiado a pie por las escarpadas laderas calizas de montaña alta, contemplando olivos tradicionales esculpidos en roca de más de 500 años y explicando las técnicas de recolección en pendientes extremas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13002','oleoturismo','Almazara de Almagro Aceites Encomienda de Cervera (Finca Encomienda de Cervera, Ctra. de Valdepeñas) y los olivares plantados sobre suelos de origen basáltico y volcánico de la comarca','(Sobresaliente por el extraordinario valor edafológico de sus suelos volcánicos y la perfecta estructura de sus packs de cata combinados con visitas a su corral de comedias). CONTROL DE LA VENTANA DE CONTEXTO Y AVANCE ALFABÉTICO: La base de datos nacional de servicios de reserva turística real ha sido expandida masivamente mediante este nuevo macro-grupo de bloques integrados. Elija el siguiente movimiento en el plan de ruta estratégico: • Continuar con el Siguiente Grupo Masivo de Bloques (Bloque 6): Desplegar simultáneamente municipios de Jaén (Alcalá la Real ampliado), Córdoba (Montoro ampliado), Badajoz (Monterrubio ampliado) y Zaragoza (Belchite ampliado). . Ruta peatonal "Olivas y Volcanes de Almagro": Paseo a pie guiado por las fincas del término municipal para observar la particular morfología de los olivares asentados sobre las tierras oscuras y ricas en minerales procedentes del vulcanismo del Campo de Calatrava.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23064','oleoturismo','S.C.A. San Isidro de Noalejo (C/ Jaén, S/N) y las parcelas montañosas que marcan el paso de Despeñaperros sur y la linde con Granada','(Excelente nota por su valor geográfico fronterizo integrado y la gran comodidad de su punto de venta directa de fábrica). 🏢 COMUNIDAD AUTÓNOMA: ANDALUCÍA. . Ruta peatonal "Olivares de Alta Pendiente": Senderismo guiado a pie por fincas que superan los 900 metros de altitud en Sierra Mágina sur, analizando la resistencia de los árboles ante heladas severas.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14066','oleoturismo','S.C.A. San Isidro de Villa del Río (Av. de la Ribera, S/N) y los olivares de la llanura aluvial del Guadalquivir alto','(Excelente nota por su alto valor cooperativo integrado y la gran comodidad de combinar oleocultura y agroturismo de proximidad). 🏢 COMUNIDAD AUTÓNOMA: EXTREMADURA. . Ruta peatonal "El Olivar de la Vega de Córdoba": Paseo a pie guiado por las parcelas de regadío controlado del término municipal, contemplando olivos centenarios integrados en un paisaje de campiña baja.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06020','oleoturismo','Almazara del Pago de Los Baldíos / Fincas de Táliga (Fincas e instalaciones integradas en el entorno transfronterizo) y los olivares tradicionales del término municipal','(Sobresaliente por el extraordinario valor etnográfico de su propuesta transfronteriza y por la perfecta estructura de sus packs de cata y almuerzo de cortijo extremeño). 🏢 COMUNIDAD AUTÓNOMA: ARAGÓN.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50143','oleoturismo','Almazara Cooperativa San Antonio de Longares (Ctra. de Zaragoza, S/N) y la red de olivares tradicionales que crecen bajo la influencia climática del Sistema Ibérico central','(Excelente nota por fusionar de forma interactiva la cultura del vino y el aceite en una misma cooperativa y por la comodidad operativa de sus packs de reserva familiar). CONTROL DE LA VENTANA DE CONTEXTO Y AVANCE ALFABÉTICO: La base de datos nacional de servicios de reserva turística real ha sido expandida masivamente mediante este nuevo macro-grupo de bloques integrados. Elija el siguiente movimiento en el plan de ruta estratégico: • Continuar con el Siguiente Grupo Masivo de Bloques (Bloque 7): Desplegar de forma simultánea municipios de Ávila (El Barraco), Cádiz (Algodonales), Sevilla (Mairena del Alcor) y Jaén (Marmolejo ampliado). . Ruta peatonal "Olivas y Viñas de Cariñena": Paseo a pie guiado por las parcelas rústicas de secano, detallando el manejo agrícola y los métodos de prepoda invernal para resistir las heladas y el azote del cierzo.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16003','oleoturismo','Almazara Institucional de Algodonales - Cooperativa Nuestra Señora del Rosario (Av. de la Constitución, S/N) y los olivares de alta pendiente colgados en la ladera norte de la Sierra de Líjar','(Excelente nota por su valor geográfico integrado y la comodidad operativa de sus packs de reserva familiar con venta directa de fábrica). 🏢 COMUNIDAD AUTÓNOMA: ANDALUCÍA. . Ruta peatonal "Olivas y Parapentes": Paseo guiado a pie por parcelas tradicionales en terrazas calizas, combinando la interpretación botánica con la observación de deportes de vuelo libre en la sierra.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41058','oleoturismo','Hacienda El Rosalejo Experiencias Alcores y los olivares tradicionales de la comarca de Los Alcores','(Excelente nota por su valor arquitectónico y la comodidad operativa de sus packs de reserva familiar con almuerzo de cortijo tradicional andaluz). 🏢 COMUNIDAD AUTÓNOMA: CASTILLA Y LEÓN. . Ruta peatonal por el Olivar del Alcor: Paseo a pie guiado entre hileras de olivos tradicionales de las variedades Manzanilla Sevillana y Gordal, conviviendo con patios andaluces barrocos.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90082','oleoturismo','Almazara Alberche Fincas del Valle de Iruelas (Ctra. de Toledo, S/N) y los olivares de ladera situados en el entorno de la Reserva Natural del Valle de Iruelas','(Excelente nota por su fuerte compromiso con las variedades de alta montaña en pendientes extremas y el extraordinario valor paisajístico de su entorno botánico). 🏢 COMUNIDAD AUTÓNOMA: ANDALUCÍA. . Ruta peatonal "Olivas y Granito de Iruelas": Paseo a pie guiado por las características terrazas escarpadas que miran al embalse de El Burguillo, observando el manejo tradicional de secano de montaña en suelos graníticos y la resistencia climática ante los inviernos de la meseta norte.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50136','oleoturismo','Almazara Cooperativa San Nicolás de Lecera (Ctra. de Zaragoza, S/N) y la red de olivares tradicionales que crecen bajo la influencia climática de las estepas del Bajo Aragón','(Excelente nota por su alto valor cooperativo integrado y por la comodidad operativa de sus packs de reserva familiar con venta directa de fábrica a precio de origen). 🏢 COMUNIDAD AUTÓNOMA: CATALUÑA. . Ruta peatonal por el Olivar Estepario: Paseo a pie guiado por las parcelas rústicas de secano, detallando el manejo agrícola y los métodos de prepoda invernal para resistir las heladas y el azote del cierzo peninsular.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43038','oleoturismo','Cooperativa de Cambrils - Mestral / Espai Oleoturisme (C/ de Sindicat, S/N) y los olivares de la llanura prelitoral del Baix Camp','(Máxima puntuación provincial por su imbatible infraestructura de atención al cliente, la excelencia de sus actividades de maridaje marinero y su enorme palmarés competitivo). 🏢 COMUNIDAD AUTÓNOMA: REGIÓN DE. . Tour de Oleoturismo Costero e Industrial: Recorrido a pie guiado por las naves históricas de almacenamiento y las modernas líneas de producción automatizada de la cooperativa, galardonada repetidamente por la calidad de sus aceites.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30024','oleoturismo','Almazara de Lorca Aceites Castillo de Lorca (Fincas e instalaciones integradas en el entorno del valle alto) y los olivares tradicionales del término municipal','(Sobresaliente por el extraordinario valor etnográfico de su propuesta fronteriza y por la perfecta estructura de sus packs de cata y almuerzo de cortijo murciano). 🏢 COMUNIDAD AUTÓNOMA: NAVARRA. . Ruta peatonal "Olivas del Valle Alto": Paseo a pie guiado por las fincas del término municipal para observar la morfología de los olivares asentados sobre las tierras de secano rústico colindantes con Almería, explicando la gestión eficiente de la baja pluviometría.','inventario_oleoturismo_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31036','oleoturismo','Trujal Mendía S.C.A. Central Arróniz (Instalaciones y fincas del entorno del municipio) y los olivares tradicionales de alta montaña de la Tierra Estella','(Máxima puntuación de la comarca norte por su tremendo valor botánico al salvaguardar y dar nombre a su variedad autóctona rústica, sumado a la impecable infraestructura de su agrotienda). CONTROL DE LA VENTANA DE CONTEXTO Y AVANCE ALFABÉTICO: La base de datos nacional de servicios de reserva turística real ha sido expandida masivamente de forma unificada mediante ocho nuevos bloques estructurales, consolidando datos geográficos precisos, nombres de empresas y propuestas gastronómicas de campo. Indique la siguiente orden de ejecución.','inventario_oleoturismo_pdf');
